INSERT INTO "document_sources" VALUES('heidelberg_catechism','Catecismo de Heidelberg','es','Catecismo de Heidelberg.pdf','3c269dae25fc1a986f1fa9bae8c662ab5deb0955e9fb06eac6d0c8a8a25e6995','Used by permission of the Reformed Church in America','https://www.rca.org/',1);
INSERT INTO "heidelberg_catechism" VALUES(1,'¿Cuál es tu único consuelo tanto en la vida como en la muerte?','Que yo, con cuerpo y alma, tanto en la vida como en la muerte, no me pertenezco a mí mismo, sino a mi fiel Salvador Jesucristo, que me libró del poder del diablo, satisfaciendo enteramente con preciosa sangre por todos mis pecados, y me guarda de tal manera que sin la voluntad de mi Padre celestial ni un solo cabello de mi cabeza puede caer antes es necesario que todas las cosas sirvan para mi salvación. Por eso también me asegura, por su Espíritu Santo, la vida eterna y me hace pronto y aparejado para vivir en adelante según su santa voluntad.','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(2,'¿Cuántas cosas debes saber para que, gozando de esta consolación, puedas vivir y morir dichosamente?','Tres: La primera, cuán grande son mis pecados y miserias. La segunda, de qué manera puedo ser librado de ellos. Y la tercera, la gratitud que debo a Dios por su redención.','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(3,'¿Cómo conoces tu miseria?','Por la Ley de Dios.','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(4,'¿Qué pide la Ley de Dios de nosotros?','Cristo nos enseñó sumariamente en Mateo cap. 22:37-40: Amarás al Señor tu Dios con todo tu corazón y con toda tu alma y con toda tu mente y con todas tus fuerzas. Este es el primero y grande mandamiento. Y el segundo es semejante: Amarás a tu prójimo como a ti mismo. De estos dos mandamientos depende toda la Ley y los Profetas.1','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(5,'¿Puedes cumplir todo esto perfectamente?','No, porque por naturaleza estoy inclinado a aborrecer a Dios y a mi prójimo.','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(6,'¿Creó, pues, Dios al hombre tan malo y perverso?','No, al contrario. Dios creó al hombre bueno haciéndolo a su imagen y semejanza, es decir, en verdadera justicia y santidad,para que rectamente conociera a Dios su Creador, le amase de todo corazón y bienaventurado viviese con El eternamente, para alabarle y glorificarle.','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(7,'¿De dónde procede esta corrupción de la naturaleza humana?','De la caída y desobediencia de nuestros primeros padres Adán y Eva en el paraíso, por ello, nuestra naturaleza ha quedado de tal manera corrompida, que todos somos concebidos y nacidos en pecado.','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(8,'¿Estamos tan corrompidos que somos totalmente incapaces de hacer el bien, e inclinados a todo mal?','Ciertamente; si no hemos sido regenerados por el Espíritu de Dios.','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(9,'¿No es Dios injusto con el hombre, al pedirle en su Ley que haga lo que no puede cumplir?','No, Dios creó al hombre en condiciones de poderla cumplir; pero el hombre por instigación del diablo y su propia rebeldía, se privó a sí y a toda su descendencia, de estos dones divinos.','Introducción','es',1,1,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(10,'¿Dejará Dios sin castigo, tal desobediencia y apostasía?','De ninguna manera; antes su ira se engrandece horriblemente, tanto por el pecado original, como por aquellos que cometemos ahora y quiere castigarlos, por su perfecta justicia, temporal o eternamente. Según ha dicho El mismo: Maldito todo aquel que no permaneciere en todas las cosas escritas en el libro de la Ley, para hacerlas.2','Introducción','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(11,'¿No es Dios también misericordioso?','Dios es misericordioso; pero también es justo. Por tanto su justicia exige que el pecado que se ha cometido contra su Suprema Majestad sea también castigado con el mayor castigo, que es pena eterna, así en el cuerpo como en el alma.','Introducción','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(12,'Si por el justo juicio de Dios merecemos penas temporales y eternas, ¿No hay alguna posibilidad de liberarnos de estas penas y reconciliarnos con Dios?','Dios quiere que se dé satisfacción a su justicia: por eso es necesario que la satisfagamos eternamente por nosotros mismos o por algún otro.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(13,'¿Pero podemos satisfacerla por nosotros mismos?','De ninguna manera: antes acrecentamos cada día nuestra deuda.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(14,'¿Podría hallar ese alguien que siendo simple criatura pagase por nosotros?','No, Primero porque Dios no quiere castigar en otra criatura, la culpa de la cual el hombre es responsable, Segundo, porque una simple criatura es incapaz de soportar la ira eterna de Dios contra el pecado y liberar a otros de ella.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(15,'¿Entonces, que mediador y redentor debemos buscar?','Uno que sea el verdadero hombre y perfectamente justo y que sea más poderoso que todas las criaturas, es decir, que sea al mismo tiempo verdadero Dios.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(16,'¿Por qué debe ser verdadero hombre y perfectamente justo?','Porque la justicia de Dios exige que la misma naturaleza humana que pecó, pague por el pecado; el hombre que es pecador, no puede pagar por otros.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(17,'¿Por qué debe ser también verdadero Dios?','Para que, por la potencia de su divinidad, pueda llevar en su humanidad la carga de la ira de Dios, y reparar y restituir en nosotros la justicia y la vida.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(18,'Mas ¿Quién es este mediador, que al mismo tiempo es verdadero Dios, y verdadero hombre perfectamente justo?','Nuestro Señor Jesucristo, el cual nos ha sido hecho por Dios, sabiduría y justicia, satisfacción y perfecta redención.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(19,'¿De dónde sabes todo esto?','Del Santo Evangelio, del cual Dios reveló primeramente en el paraíso, y después lo anunció por los santos patriarcas y profetas, y lo hizo representar por los sacrificios y las demás ceremonias de la Ley: y al fin lo cumplió por su Hijo unigénito.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(20,'¿Son salvados por Cristo todos los hombres que perecieron en Adán?','No todos, sino sólo aquellos que por la verdadera fe son incorporados en El y aceptan sus beneficios.','La Redención del Hombre','es',2,2,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(21,'¿Qué es la verdadera fe?','No es sólo un seguro conocimiento por el cual considero cierto todo lo que el Señor nos ha revelado en su palabra, sino también una verdadera confianza que el Espíritu Santo, infunde en mi corazón, por el Evangelio, dándome la seguridad, de que no sólo a otros sino también a mí mismo Dios otorga la remisión de pecados, la justicia y la vida eterna, y eso de pura gracia y solamente por los méritos de Jesucristo.','La Redención del Hombre','es',3,3,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(22,'¿Qué es lo que debe creer el Cristiano?','Todo lo que se nos ha prometido en el Santo Evangelio, sumariamente contenido en el Símbolo Apostólico, en cuyos artículos se expresa la fe universal e infalible de todos los cristianos.','La Redención del Hombre','es',3,3,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(23,'¿Qué dicen estos artículos?','Creo en Dios Padre, todopoderoso, Creador del cielo y de la tierra. Creo en Jesucristo su único hijo, nuestro Señor; que fue concebido por el Espíritu Santo, nació de María Virgen; padeció bajo el poder de Poncio Pilato, fue crucificado, muerto y sepultado; descendió a los infiernos, y al tercer día resucitó de entre los muertos; subió a los cielos; está sentado a la diestra de Dios, Padre todopoderoso, de donde vendrá a juzgar a los vivos y a los muertos. Creo en el espíritu Santo; una Santa Iglesia cristiana católica, la Comunión de los Santos; la remisión de los pecados, la resurrección del cuerpo y la vida eterna. Amén.','La Redención del Hombre','es',3,3,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(24,'¿En cuántas partes se dividen estos artículos?','En tres. La Primera: De Dios Padre y de nuestra creación. La Segunda: De Dios Hijo y de nuestra redención. La Tercera: De Dios Espíritu Santo y nuestra santificación.','La Redención del Hombre','es',3,3,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(25,'Si no hay más que una Esencia Divina, ¿Por qué nombras tres: Padre, Hijo y Espíritu Santo?','Porque Dios se manifestó así en su palabra, de manera que estas tres personas son el único, verdadero y eterno Dios.','La Redención del Hombre','es',3,3,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(26,'¿Qué crees cuando dices: creo en Dios Padre Todopoderoso, creador del cielo y de la tierra?','Creo en el Padre de nuestro Señor Jesucristo, quien de la nada creó el cielo y de la tierra, con todo lo que en ellos hay, sustentándolo y gobernándolo todo por su eterno consejo y providencia, es mi Dios y mi Padre por amor de su hijo Jesucristo, En él confío de tal manera que no dudo de que me proveerá de todo lo necesario para mi alma y mi cuerpo. Y aún más, creo que todos los males que puedo sufrir por su voluntad, en este valle de lágrimas, los convertirá en bien para mi salvación. Él puede hacerlo como Dios todopoderoso, y quiere hacerlo como Padre benigno y fiel.','De Dios Padre','es',3,3,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(27,'¿Qué es la providencia de Dios?','Es el poder de Dios omnipotente y presente en todo lugar, por el cual sustenta y gobierna el cielo, la tierra y todas las criaturas de tal manera, que todo lo que la tierra produce, la lluvia y la sequía, la fertilidad y la esterilidad, la comida y la bebida, la salud y la enfermedad, riquezas y pobrezas, y finalmente todas las cosas no acontecen sin razón alguna como por azar, sino por su consejo y voluntad paternal.','De Dios Padre','es',3,3,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(28,'¿Qué utilidad tiene para nosotros este conocimiento de la creación y providencia divina?','Que en toda adversidad tengamos paciencia, y en la prosperidad seamos agradecidos, y tengamos puesta en el futuro, toda nuestra esperanza en Dios nuestro padre fidelísimo, sabiendo con certeza que no hay cosa que nos puede apartar de su amor, pues todas las criaturas, están sujetas a su poder de tal manera que no pueden hacer nada sin su voluntad.','De Dios Padre','es',3,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(29,'¿Por qué el hijo de Dios es llamado Jesús, que significa Salvador?','Porque nos salva y libra de todos nuestros pecados, y porque en ningún otro se debe buscar ni se puede hallar salvación.','De Dios Hijo','es',4,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(30,'¿Creen pues también en el único Salvador Jesús, aquellos que buscan su salvación en los santos, o en sí mismos o en cualquiera otra parte?','No, porque aunque de boca se gloríen de tenerle por Salvador, de hecho niegan al único Salvador Jesús: pues necesariamente resulta, o que Jesús no es perfecto Salvador o que aquellos que con verdadera fe le reciben por Salvador tienen que poseer en El todo lo necesario para su salvación.','De Dios Hijo','es',4,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(31,'¿Por qué se le llama Cristo, es decir: ungido?','Porque fue ordenado del Padre y ungido del Espíritu Santo, para ser nuestro supremo profeta y maestro, que nos ha revelado plenamente el secreto consejo y voluntad de Dios acerca de nuestra redención, para ser nuestro único y supremo pontífice quien por el sólo sacrificio de su cuer po nos ha redimido, e intercede continuamente delante del Padre por nosotros, para ser nuestro eterno Rey que nos gobierna por su palabra y su espíritu y nos guarda y conserva la redención que nos ha adquirido.','De Dios Hijo','es',4,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(32,'Pues, ¿Porqué te llaman Cristiano?','Porque por la fe soy miembro de Jesucristo y participante de su unción, para que confiese su nombre y me ofrezca a Él, en sacrificio vivo y agradable y que en esta vida luche contra el pecado y Satanás con una conciencia limpia y buena y que, después de esta vida reine con Cristo eternamente sobre todas las criaturas.','De Dios Hijo','es',4,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(33,'¿Por qué se llama a Cristo el unigénito hijo de Dios, si nosotros también somos hijos de Dios?','Porque Cristo es el hijo eterno y natural de Dios; pero nosotros hemos sido adoptados por gracia como hijos de Dios por amor de él.','De Dios Hijo','es',4,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(34,'¿Por qué le llamamos nuestro Señor?','Por que rescatando nuestros cuerpos y almas de los pecados, no con oro o plata, sino con su preciosa sangre, y librándonos del poder del Diablo, nos ha hecho suyos.','De Dios Hijo','es',4,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(35,'¿Qué crees cuando dices: que fue concebido por el Espíritu santo y nació de María virgen?','Que el eterno Hijo de Dios, el cual es y permanece verdadero y eterno Dios, tomó la naturaleza verdaderamente humana de la carne y sangre de la virgen María, por obra del Espíritu Santo, para que juntamente fuese la verdadera simiente de David, semejante a sus hermanos excepto en el pecado.','De Dios Hijo','es',4,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(36,'¿Qué fruto sacas de la santa concepción y nacimiento de Cristo?','Que es nuestro Mediador, y con su inocencia y perfecta santidad cubre mis pecados en los cuales he sido concebido y nacido, para que no aparezcan en la presencia de Dios.','De Dios Hijo','es',4,4,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(37,'¿Qué es lo que crees cuando dices: padeció?','Que todo el tiempo que en este mundo vivió y especialmente al fin de su vida, sostenía en el cuerpo y el alma la ira de Dios contra el pecado de todo el género humano, para que con su pasión, como único sacrificio propiciatorio, librara nuestro cuerpo y alma de la eterna condenación, y nos alcanzase la gracia de Dios, la justicia y la vida eterna.','De Dios Hijo','es',4,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(38,'¿Por qué padeció bajo el poder de Poncio Pilato juez?','Para que, inocente, condenado por el juez político, nos librase del severo juicio de Dios, que había de venir sobre nosotros.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(39,'¿Es más importante el haber sido crucificado, que morir de otro modo?','Sí, porque este género de muerte me garantiza que él cargó sobre sí mismo la maldición sentenciada sobre mí, por cuanto la muerte de cruz era maldita de Dios.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(40,'¿Por qué fue necesario que Cristo se humillase hasta la muerte?','Porque la justicia de Dios no se podía satisfacer por nuestros pecados, sino con la misma muerte del Hijo de Dios.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(41,'¿Por qué fue también sepultado?','Para testificar que estaba verdaderamente muerto.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(42,'Ya que Cristo murió por nosotros, ¿Por qué hemos de morir también nosotros?','Nuestra muerte no es una satisfacción por nuestros pecados, sino una liberación del pecado y un paso hacia la vida eterna.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(43,'¿Qué provecho recibimos además del sacrificio y muerte de Cristo en la cruz?','Por su poder nuestro viejo hombre está crucificado, muerto y sepultado juntamente con Él, para que, en adelante, no reinen más en nosotros las perversas concupiscencias y deseos de la carne, sino que nos ofrezcamos a Él en sacrificio agradable.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(44,'¿Por qué se añade: descendió a los infiernos?','Para que en mis extremados dolores y grandísimas tentaciones me asegure y me sostenga con este consuelo, de que mi Señor Jesucristo, por medio de las inexplicables angustias, tormentos, espantos y turbaciones infernales de su alma, en los cuales fue sumido en toda su pasión, pero especialmente clavado en la cruz, me ha librado de las ansias y tormentos del infierno.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(45,'¿Qué nos aprovecha la resurrección de Cristo?','Primero: Por su resurrección ha vencido a la muerte, para hacernos participantes de aquella justicia que conquistó por su muerte. Segundo: También nosotros somos resucitados ahora por su poder a una nueva vida. Tercero: la resurrección de Cristo, cabeza nuestra, es una cierta prenda de nuestra gloriosa resurrección.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(46,'¿Qué entiendes por: subió a los cielos?','Que Cristo, a la vista de sus discípulos, fue elevado de la tierra al cielo y que está allí para nuestro bien, hasta que vuelva a juzgar a los vivos y a los muertos.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(47,'Luego, ¿No está Cristo con nosotros hasta el fin del mundo como lo prometido?.','Cristo es verdadero Dios y verdadero hombre: en cuanto a la naturaleza humana ahora ya no está en la tierra, pero en cuanto a su deidad, majestad, gracia y espíritu en ningún momen to está ausente de nosotros.','De Dios Hijo','es',5,5,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(48,'Pero si la naturaleza humana no está en todas partes donde está la divina ¿No se separan con esto las dos naturalezas en Cristo?','De ninguna manera: porque dado que la divinidad es incomprensibley está presente en todo lugar, resulta necesariamente que en efecto está fuera de la naturalezahumana que ha tomado, perocon todo y con eso está en ella y queda unida a ella personalmente.','De Dios Hijo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(49,'¿Qué beneficios nos da la ascensión de Cristo al cielo?','Primero: Él es nuestro intercesor en el cielo delante del Padre. Segundo: Que tenemos nuestra carne en el cielo para que por ello, como una garantía, estemos seguros, de que él siendo nuestra cabeza, nos atraerá a sí como miembros suyos. Tercero. Que desde allí nos envía su Espíritu como prenda recíproca, por cuya virtud buscamos, no las cosas de la tierra sino las de arriba, donde está sentado a la diestra de Dios.','De Dios Hijo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(50,'¿Por qué se añade: está sentado a la Diestra de Dios, Padre todopodero so?','PorqueCristo subió al cielo para mostrarse allí como cabeza de su Iglesia, por quien el Padre gobierna todas las cosas.','De Dios Hijo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(51,'¿De qué nos sirve esta gloria de Cristo, nuestra cabeza?','Primero: Para que el Espíritu Santo derrame en nosotros, sus miembros, los dones celestiales, y Segundo: Para protegernos y ampararnos de todos nuestros enemigos.','De Dios Hijo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(52,'¿Qué consuelo te ofrece la vuelta de Cristo para juzgar a los vivos y a los muertos?','Que en todas las miserias y persecuciones, con plena confianza, espero del cielo como juez, a Aquel mismo que primeramente se puso delante del juicio de Dios por mí y alejó de mí toda maldición; el cual echará a todos los enemigos suyos y míos en las penas eternas; y a mí, con todos los elegidos, me conducirá al gozo del cielo y a la gloria eterna.','De Dios Hijo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(53,'¿Qué crees del Espíritu Santo?','Que con el Eterno Padre e Hijo, es verdadero y eterno Dios. Y que viene a morar en mí para que, por la verdadera fe, me haga participante de Cristo y de todos sus beneficios, me consuele y quede conmigo eternamente.','De Dios Espíritu Santo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(54,'¿Qué crees de la santa Iglesia cristiana católica?','Que el Hijo de Dios, desde el principio hasta el fin del mundo, de todo el género humano, congrega, guarda y protege para sí, por su Espíritu y su palabra en la unidad de la verdadera fe, una comunidad, elegida para la vida eterna; de la cual yo soy un miembro vivo y permaneceré para siempre.','De Dios Espíritu Santo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(55,'¿Qué entiendes por la comunión de los santos?','Primero, que todos los fieles en general y cada uno en particular, como miembros del Señor Jesucristo, tienen la comunión de Él y de todos sus bienes y dones. Segundo, que cada uno debe sentirse obligado a emplear con amor y gozo los dones que ha recibido, utilizándolos en beneficio de los demás.','De Dios Espíritu Santo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(56,'¿Qué crees de la remisión de los pecados?','Creo que Dios, por la satisfacción de Cristo, no quiere acordarse jamás de mis pecados, ni de mi naturaleza corrompida, con la cual debo luchar toda la vida, sino que gratuitamente me otorga la justicia de Cristo para que yo nunca venga a condenación.','De Dios Espíritu Santo','es',6,6,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(57,'¿Qué consuelo te da la resurrección de la carne?','Que no sólo mi alma después de esta vida será llevada en el mismo instante a Cristo, su cabeza, sino que también está mi carne, siendo resucitada por la potencia de Cristo, será de nuevo unida a mi alma y hecha conforme al glorioso cuerpo de Cristo.','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(58,'¿Qué consolación te ofreceel artículo de la vida eterna?','Que ahora siento en mi corazón un principio de la vida eterna, después de esta vida, gozaré de una cumplida y perfecta bienaventuranza que ningún ojo vio ni oído oyó, ni entendimiento humano comprendió, y esto para que ella alabe a Dios para siempre ( b).','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(59,'¿Qué te aprovecha el creer en todas estas cosas?','Que delante de Dios soy justo en Jesucristo,y heredero de la vida eterna.','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(60,'¿Cómo eres justo ante Dios?','Por la sola verdadera fe en Jesucristo, de tal suerte que, aunque mi conciencia me acuse de haber pecado gravemente contra todos los mandamientos de Dios, no habiendo guardado jamás ninguno de ellos,y estando siempre inclinado a todo mal, sin merecimiento alguno mío, sólo por su gracia, Dios me imputa y da la perfecta satisfacción, justicia y santidad de Cristo como si no hubiera yo tenido, ni cometido algún pecado, antes bien como si yo mismo hubiera cumplido aquella obediencia que Cristo cumplió por mí, con tal que yo abrace estas gracias y beneficios con verdadera fe.','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(61,'¿Por qué afirmas ser justo sólo por la fe?','No porque agrade a Dios por la dignidad de mi fe, sino porque sólo la satisfacción, justicia y santidad de Cristo, son mi propia justicia delante de Dios, y que yo no puedo cumplir de otro modo que por la fe.','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(62,'¿Por qué no pueden justificarnos ante Dios las buenas obras, aunque sólo sea una parte?','Porque es necesario que aquella justicia, que ha de aparecer delante del juicio de Dios, sea perfectamente cumplida y de todo punto conforme a la Ley Divina; y nuestras buenas obras, aun las mejores en esta vida, son imperfectas y contaminadas de pecado.','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(63,'Luego, ¿Cómo es posible que nuestras obras no merezcan nada, si Dios promete remunerarlas en la vida presente y en la venidera?','Esta remuneración no se da por merecimiento, sino por gracia.','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(64,'Pero esta doctrina, ¿no hace a los hombres negligentes e impíos?','No, porque es imposible que no produzcan frutos de gratitud los que por la fe verdadera han sido injertados en Cristo.','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(65,'Si sólo la fe nos hace participantes de Cristo y de todos sus beneficios, dime, ¿de dónde procede esta fe?','Del Espíritu Santo que la hace obrar por la predicación del Santo Evangelio, encendiendo nuestros corazones, y confirmándola por el uso de los sacramentos.','De Dios Espíritu Santo','es',7,7,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(66,'¿Qué son los Sacramentos?','Son señales sagradas y visibles, y sellos instituidos por Dios, para sernos declarada mejor y sellada por ellos la promesa del Evangelio; a saber, que la remisión de los pecados y la vida eterna, por aquel único sacrificio de Cristo cumplido en la cruz, se nos da de gracia no solamente a todos los creyentes en general, sino también a cada uno en particular.','De los Sacramentos','es',7,8,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(67,'Entonces la palabra y los Sacramentos ¿tienen como fin llevar nuestra fe al sacrificio de Cristo cumplido en la cruz, como el único fundamento de nuestra salvación?','Así es, porque el Espíritu Santo nos enseña por el Evangelio y confirma por los Sacramentos, que toda nuestra salud está puesta en el único sacrificio de Cristo ofrecido por nosotros en la cruz.','De los Sacramentos','es',8,8,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(68,'¿Cuántos sacramentos ha instituido Cristo en el Nuevo Testamento?','Dos: El Santo Bautismo y la Santa Cena.','De los Sacramentos','es',8,8,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(69,'¿Por qué el Santo bautismo te asegura y recuerda que eres participante de aquel único sacrificio de Cristo, hecho en la Cruz?','Porque Cristo ha instituido, el lavamiento exterior del agua, añadiendo esta promesa, que tan ciertamente soy lavado con su sangre y Espíritu de las inmundicias de mi alma, es a saber, de todos mis pecados, como soy rociado y lavado exteriormente con el agua, con la cual se suelen limpiar las suciedades del cuerpo.','Del Santo Bautismo','es',8,8,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(70,'¿Qué es ser lavado con la sangre y el Espíritu de Cristo?','Es recibir de la gracia de Dios, la remisión de los pecados, por la sangre de Cristo, que derramó por nosotros en su sacrificio en la Cruz. Y también ser renovados y santificados por el Espíritu Santo, para ser miembros de Cristo, a fin de que muramos al pecado y vivamos santa e irreprensiblemente.','Del Santo Bautismo','es',8,8,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(71,'¿Dónde prometió Cristo que Él nos quiere limpiar tan ciertamente por su sangre y Espíritu como somos lavados por el agua del bautismo?','En la institución del Bautismo, cuyas palabras son éstas: "Id, enseñad a todas las gentes, bautizándolas en el nombre del Padre y del Hijo, y del Espíritu Santo" (Mateo 28:19) 3 "El que creyere y fuere bautizado, será salvo; mas el que no creyere, será condenado" (Marcos 16:16). 4 Esta misma promesa se repite cuando las Sagradas escrituras llaman al bautismo "lavamiento de la regeneración y ablución de pecados" (Tito 3:5, Hechos 22:16).5','Del Santo Bautismo','es',8,8,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(72,'¿Es el lavamiento, la purificación misma de los pecados?','No: porque sólo la sangre de Jesucristo y el Espíritu Santo nos limpia y purifica de todo pecado.','Del Santo Bautismo','es',8,8,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(73,'Entonces, ¿Por qué llama el Espíritu Santo al bautismo el lavado de la regeneración y la purificación de los pecados?','Dios no habla así sin una razón justificada, pues Él, no sólo quiere enseñarnos que nuestros pecados se purifican por la sangre y el Espíritu de Cristo, como las suciedades del cuerpo por el agua, sino más aún: certificarnos por este divino símbolo y prenda que verdaderamente somos limpiados por el lavamiento interior y espiritual de nuestros pecados, de la misma manera que somos lavados exteriormente por el agua visible.','Del Santo Bautismo','es',8,8,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(74,'¿Se ha de bautizar también a los niños?','Naturalmente, porque están comprendidos, como los adultos, en el pacto, y pertenecen a la iglesia de Dios. Tanto a éstos como a los adultos se les promete por la sangre de Cristo, la remisión de los pecados y el Espíritu Santo, obrador de la fe; por esto, y como señal de este pacto, deben ser incorporados a la Iglesia de Dios y diferenciados de los hijos de los infieles, así como se hacía en el pacto del Antiguo Testamento por la circuncisión, cuyo sustito es el Bautismo en el Nuevo Pacto.','Del Santo Bautismo','es',8,9,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(75,'¿Cómo te asegura y confirma la Santa Cena que eres hecho participante de aquel único sacrificio de Cristo, ofrecido en la cruz, y de todos sus bienes?','Porque Cristo me ha mandado, y también a todos los fieles, comer de este pan partido y beber de esta copa en memoria suya, añadiendo esta promesa: Primero, que su cuerpo ha sido ofrecido y sacrificado por mí en la cruz, y su sangre derramada por mis pecados, tan cierto como que veo con mis ojos que el pan del Señor es partido para mí y que me es ofrecida la copa. Y Segundo, que El tan cierto alimenta mi alma para la vida eterna con su cuerpo crucificado y con su sangre derramada, como yo recibo con la boca corporal de la mano del ministro el pan y el vino, símbolos del cuerpo y de la sangre del Señor.','De la Santa Cena de Nuestro Señor','es',9,9,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(76,'¿Qué significa comer el cuerpo sacrificado de Cristo y beber su sangre derramada?','Significa, no sólo abrazar con firme confianza del alma toda la pasión y muerte de Cristo, y por este medio alcanzar la remisión de pecados y la vida eterna, sino unirse más y más a su santísimo cuerpo por el Espíritu Santo, el cual habita juntamente en Cristo y en nosotros de tal manera, que, aunque El esté en el cielo y nosotros en la tierra, todavía somos carne de su carne y huesos de sus huesos, y que, de un mismo espíritu, (como todos los miembros del cuerpo por una sola alma) somos vivificados y gobernados para siempre.','De la Santa Cena de Nuestro Señor','es',9,9,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(77,'¿Dónde prometió Cristo, que tan ciertamente dará a los creyentes en comida y en bebida su cuerpo y sangre, como comen de este pan roto y beben de este vaso?','En la institución de la cena, cuyas palabras fueron: Nuestro Señor Jesucristo, la noche que fue entregado, tomó el pan, y habiendo dado gracias, lo partió y dijo: Tomad, comed, esto es mi cuerpo que por vosotros es partido; haced en memoria de mí. Asimismo tomó también la copa, después de haber cenado, diciendo: Esta copa es el nuevo pacto en mi sangre;haced esto todas las veces que la bebereis, en memoria de mí. Así, pues, todas las veces que comiereis este pan y bebiereis esta copa, la muerte del Señor anunciáis hasta que él venga (1 Cor. 11:23-26).6 Pablo repite esta promesa cuando dice: La copa de bendición, que bendecimos, ¿no es la comunión de la sangre de Cristo?, El pan que partimos, ¿no es la comunión del cuerpo de Cristo? Siendo uno solo el pan, nosotros, con ser muchos, somos un cuerpo: pues todos participamos de aquel mismo pan (1 Cor. 10:16,17).7','De la Santa Cena de Nuestro Señor','es',9,9,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(78,'¿El pan y el vino se convierten sustancialmente en el mismo cuerpo y sangre de Cristo?','De ninguna manera, pues como el agua del Bautismo no se convierte en la sangre de Cristo, ni es la misma ablución de los pecados, sino solamente una señal y sello de aquellas cosas que nos son selladas en el Bautismo, así el pan de la Cena del Señor no es el mismo cuerpo, aunque por la naturaleza y uso de los sacramentos es llamado el cuerpo de Cristo.','De la Santa Cena de Nuestro Señor','es',9,9,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(79,'¿Por qué llama Cristo al pan su cuerpo y a la copa su sangre, o el Nuevo Testamento en su sangre, y Pablo al pan y al vino la comunión del cuerpo y sangre de Cristo?','Cristo no habla así sin una razón poderosa, y no solamente para enseñarnos que, así como el pan y el vino sustentan la vida corporal, su cuerpo crucificado y su sangre derramada son la verdadera comida y bebida, que alimentan nuestras almas para la vida eterna, más aún, para asegurarnos por estas señales y sellos visibles, que por obra del Espíritu Santo somos participantes de su cuerpo y sangre tan cierto como que tomamos estos sagrados símbolos en su memoria y por la boca del cuerpo; y también que su pasión y obediencia son tan ciertamente nuestras ,como si nosotros mismos en nuestras personas hubiéramos sufrido la pena y satisfecho a Dios por nuestros pecados.8','De la Santa Cena de Nuestro Señor','es',9,10,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(80,'¿Quiénes son los que deben participar de la mesa del Señor?','Tan sólo aquellos que se duelan verdaderamente de haber ofendido a Dios con sus pecados, confiando en ser perdonados por el amor de Cristo y que las demás flaquezas quedarán cubiertas con su pasión y muerte. Y que también deseen fortalecer más y más su fe y mejorar su vida. Pero los hipócritas y los que no se arrepienten de verdad, comen y beben su condenación.','De la Santa Cena de Nuestro Señor','es',10,10,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(81,'¿Deben admitirse también a esta Cena, los que por su confesión y vida se declaran infieles e impíos?','De ninguna manera, porque así se profana el pacto de Dios, y se provoca su ira sobre toda la congregación. Por lo cual, la Iglesia debe, según la orden de Cristo y de sus apóstoles (usando de las llaves del reino de los cielos), excomulgar y privar a los tales de la Cena, hasta que se arrepientan y rectifiquen su vida.','De la Santa Cena de Nuestro Señor','es',10,10,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(82,'¿Qué son las llaves del reino de los cielos?','La predicación del Santo Evangelio y la disciplina eclesiástica: con los cuales se abre el cielo a los fieles, y se cierra a los infieles.','De la Santa Cena de Nuestro Señor','es',10,10,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(83,'¿De qué manera se abre y se cierra el reino de los cielos por la predicación del Evangelio?','Cuando (según el mandamiento de Cristo) públicamente es anunciado y testificado a todos los fieles en general y a cada uno en particular, que todos los pecados les son perdonados por Dios, por los méritos de Cristo, todas las veces que abrazaren con verdadera fe la promesa del evangelio. Al contrario, a todos los infieles e hipócritas, se les anuncia que la ira de Dios y la condenación eterna  caerá sobre ellos mientras perseveraren en su maldad; según testimonio del Evangelio, Dios juzgará así en esta vida como en la otra.','De la Santa Cena de Nuestro Señor','es',10,10,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(84,'¿De qué manera se cierra y se abre el reino de los cielos por la disciplina eclesiástica?','Cuando (según el mandamiento de Cristo) aquellos que bajo el nombre de cristianos se muestran en la doctrina o en la vida ajenos a Cristo, y después de haber sido fraternalmente amonestados en diversas ocasiones, no quieren apartarse de sus errores o maldades, son denunciados a la Iglesia o a los que han sido amonestados por ella. Y si aun no obedecen a la amonestación de éstos, por la prohibición de los sacramentos, son expulsados de la congregación cristiana, y por el mismo Dios, del reino de Cristo; y otra vez recibidos, como miembros de Cristo y de su Iglesia, cuando prometen enmienda y lo demuestran por sus obras.','De la Santa Cena de Nuestro Señor','es',10,10,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(85,'Si somos liberados por Cristo de todos nuestros pecados y miserias sin merecimiento alguno de nuestra parte, sino sólo por la misericordia de Dios ¿Por qué hemos de hacer buenas obras?','Porque después de que Cristo nos ha redimido con su sangre, nos renueva también con su Espíritu Santo a su imagen; a fin de que en toda nuestra vida nos mostremos agradecidos a Dios por tantos beneficios y que Él sea glorificado por nosotros. Además de esto para que cada uno de nosotros sea asegurado de su fe por los frutos. Y finalmente para que, también por la piedad e integridad de nuestra vida, ganemos a nuestro prójimo para Cristo.','De la Gratitud','es',10,10,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(86,'Luego, ¿No pueden salvarse aquellos que siendo desagradecidos y perseverando en sus pecados no se conviertan a Dios de su maldad?','De ninguna manera, porque, como lo testifican las Sagradas Escrituras, no herederán el reino de Dios los fornicarios, los idólatras, los adúlteros, los ladrones, los avaros, los borrachos, los maldicientes.','De la Gratitud','es',11,11,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(87,'¿De cuantas partes se compone el verdadero arrepentimiento y conversión al Señor?','De dos: la muerte del viejo hombre, y la vivificación del nuevo.9','De la Gratitud','es',11,11,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(88,'¿En qué consiste la muerte del hombre viejo?','En que sintamos pesar, de todo corazón, de haber ofendido a Dios con nuestros pecados, aborreciéndolos y evitándolos.','De la Gratitud','es',11,11,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(89,'¿Qué es la vivificación del nuevo hombre?','Es alegrarse de todo corazón en Dios por Cristo, y desear vivir conforme a la voluntad de Dios, así como ejercitarse en toda buena obra.','De la Gratitud','es',11,11,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(90,'¿Qué son las buenas obras?','Únicamente aquellas que se realizan con fe verdadera, conforme a la Ley de Dios, y se aplican solamente a su gloria; y no aquellas que están fundadas en nuestras buenas intenciones o sobre instituciones humanas.','De la Gratitud','es',11,11,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(91,'¿Cuál es la Ley de Dios?','Y habló Dios todas estas palabras (Éxodo 20:1-17): PRIMER MANDAMIENTO: No tendrás dioses ajenos delante de mí. SEGUNDO MANDAMIENTO: No te harás imagen, ni ninguna semejanza de lo que esté arriba en el cielo, ni abajo en la tierra, ni en las aguas debajo de la tierra, No te inclinarás a ellas, ni las honrarás; porque yo soy Jehová tu Dios, fuerte, celoso, que visitó la maldad de los padres sobre los hijos, hasta la tercera y cuarta generación, de los que me aborrecen; y hago misericordia a millares, a los que me aman y guardan mis mandamientos. TERCER MANDAMIENTO: No tomarás el nombre de Jehová tu Dios en vano; porque no dará por inocente Jehová al que tomare su nombre en vano. CUARTO MANDAMIENTO: Acuérdate del día de reposo para santificarlo; seis días trabajarás, y harás toda su obra; mas el séptimo día es de reposo para Jehová tu Dios; no hagas en él obra alguna, tú ni tu hijo, ni tu hija ni tu siervo ni tu criada ni tu bestia, ni tu extranjero que está dentro de tus puertas. Porque en seis días hizo Jehová los cielos y la tierra, el mar y todas las cosas que en ellos hay, y reposó en el séptimo día; por tanto, Jehová bendijo el día de reposo y lo santificó. QUINTO MANDAMIENTO: Honra a tu padre y a tu madre, para que tus días se alarguen en la tierra que Jehová tu Dios te da. SEXTO MANDAMIENO: No matarás. SEPTIMO MANDAMIENO: No cometerás adulterio. OCTAVO MANDAMIENTO: No hurtarás. NOVENO MANDAMIENTO: No hablarás contra tu prójimo falso testimonio. DECIMO MANDAMIENTO: No codiciarás la casa de tu prójimo, no codiciarás la mujer de tu prójimo ni su siervo, ni su criada, ni su buey, ni su asno, ni cosa alguna de tu prójimo.','De la Ley','es',11,12,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(92,'¿Cómo se dividen estos diez mandamientos?','En dos tablas: De las cuales la primera enseña lo que debemos hacer para con Dios; la segunda, lo que debemos hacer para con nuestro prójimo.10','De la Ley','es',12,12,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(93,'¿Qué manda Dios en el primer mandamiento?','Que yo, que deseo la salvación de mi alma, evite y huya de toda idolatría, hechicería, encantamiento, superstición, invocación de santos y de otras criaturas; y que conozca rectamente al único verdadero Dios, en El sólo confié con toda humildad y paciencia, a El que de todo corazónle ame, tema y reverencie; de tal manera que esté dispuesto a renunciar a todas las criaturas antes que cometer la menor cosa contra su voluntad.','De la Ley','es',12,12,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(94,'¿Qué es idolatría?','Es poner en el lugar que sólo corresponde al Dios verdadero que se ha revelado por su Palabra, o junto a Él, cualquier otra cosa en la cual se ponga confianza.','De la Ley','es',12,12,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(95,'¿Qué pide Dios en el segundo mandamiento?','Que no representemos a Dios por medio de alguna imagen o figura, y sólo le rindamos culto como Él ha mandado en su Palabra.','De la Ley','es',12,12,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(96,'¿No es lícito hacer ninguna imagen?','Ni podemos, ni debemos representar a Dios de ninguna manera, y aun en el caso de que fuese lícito representar a las criaturas, Dios prohíbe hacer o poseer ninguna imagen destinada a ser adorada o empleada en su servicio.','De la Ley','es',12,12,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(97,'¿No se podrían tolerar las imágenes en las iglesias, como si fuesen libros para enseñar a los ignorantes?','No, porque nosotros no debemos ser más sabios que Dios, que no quiere instruir a su pueblo por imágenes mudas, sino por la predicación viva de su Palabra.','De la Ley','es',12,12,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(98,'¿Qué nos enseña el tercer mandamiento?','Que dejemos de blasfemar o profanar el nombre de Dios por medio de falsos juramentos y maldiciones, y aún inútiles juramentos; que no nos hagamos partícipes de tan horrendos pecados al callar cuando los oigamos. En una palabra: que no empleemos el santo nombre de Dios , mas que con temor y veneración, a fin de que Él sea rectamente confesado, invocado y glorificado por nuestras palabras y hechos.','De la Ley','es',12,12,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(99,'¿Es tan grave pecado el profanar el nombre de Dios por medio de juramentos y blasfemias, que Dios también se enoja contra aquellos que no se opusieron y no lo prohibieron con todas sus fuerzas?','Sí, porque no hay mayor pecado ni cosa que a Dios más ofenda que el profanar su nombre, por lo cual mandó que esta maldad fuese castigada con la muerte.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(100,'¿Se puede jurar santamente en nombre de Dios?','Sí, cuando el magistrado o la necesidad así lo exijan para sostener y confirmar la fe y la verdad, para la gloria de Dios y el bien de nuestro prójimo. Pues tal manera de prestar juramento está fundada en la palabra de Dios y, en consecuencia, ha sido rectamente empleada por los santos, tanto en el Antiguo como en el Nuevo Testamento.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(101,'¿Es lícito jurar por los santos u otras criaturas?','No. Porque el legítimo juramento es una invocación de Dios, por la cual se le pide, que Él, como el que sólo ve los corazones, sea testigo de la verdad, y castigue si el juramento es falso; este honor le corresponde a Él.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(102,'¿Qué ordena Dios en el cuarto mandamiento?','Primero, que el ministerio de la Palabra y la enseñanza sean mantenidos, y que yo frecuente asiduamente la iglesia, la congregación de Dios, sobre todo el día de reposo, para oír la Palabra de Dios, y participar de los santos sacramentos, para invocar públicamente al Señor, y para contribuir cristianamente a ayudar a los necesitados. Además, que todos los días de mi vida cese de mal obrar, para que sea Dios mismo quien obre en mi corazón por su Espíritu, y de este modo pueda empezar en esta vida el Sábado eterno.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(103,'¿Qué manda Dios en el quinto mandamiento?','Que muestre a mi padre y a mi madre y a todos mis superiores, honor, amor y fidelidad, que me someta obedientemente a sus buenas enseñanzas y castigos, soportando  también pacientemente sus flaquezas, pues Dios quiere regirnos por medio de ellos.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(104,'¿Qué exige Dios en el sexto mandamiento?','Que ni por mis pensamientos, palabras, actitud y aún menos por mis actos, por mí mismo o por medio de otro, llegue a injuriar, odiar, ofender o matar a mí prójimo, por el contrario que, renuncie a todo deseo de venganza; que no me haga mal a mi mismo o me exponga temerariamente al peligro. Para impedir esto, el magistrado posee la espada.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(105,'¿Este mandamiento sólo prohíbe matar?','Al prohibir la muerte Dios nos enseña que Él detesta todo lo que de ello se origina, como la envidia, el odio, la ira y el deseo de venganza, considerando todo esto como verdadero homicidio.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(106,'¿Es suficiente, como hemos dicho, el no matar a nuestro prójimo?','No; pues Dios, condenando la envidia, el odio y la ira, quiere que amemos a nuesro prójimo como a nosotros mismos, usando para con él toda benignidad, mansedumbre, paciencia y misericordia, impidiendo hasta donde nos sea posible,el mal que le podría sobrevenir, haciendo bien incluso a nuestros enemigos.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(107,'¿Qué enseña el séptimo mandamiento?','Que Dios maldice toda deshonestidad, y en consecuencia nosotros debemos también aborrecerla de todo corazón y vivir casta y sobriamente, sea en el santo estado de matrimonio, o en otro estado.','De la Ley','es',13,13,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(108,'¿En este mandamiento, prohíbe sólo Dios el adulterio y pecados semejantes?','Como nuestro cuerpo y alma son templo del Espíritu Santo, Dios quiere que conservemos ambos puros y santos.Para ello prohíbe toda impureza en nuestras acciones, nuestros gestos, nuestras palabras, nuestros pensamientos y deseos, y todo lo que incita al hombre a ello.','De la Ley','es',14,14,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(109,'¿Qué prohíbe Dios en el octavo mandamiento?','Dios prohíbe no solamente el robo y la rapiña que castiga la autoridad , sino que llama también robo a todos los medios malos y engaños con los cuales tratamos de apoderarnos del bien de nuestro prójimo, ya sea por la fuerza por una apariencia de derecho, como son: el peso falso,la mala mercadería, la moneda falsa, la usura, o por cualquier otro medio prohibido por Dios. También prohíbe toda avaricia y todo uso inútil de sus dones.','De la Ley','es',14,14,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(110,'¿Qué te ordena Dios en este mandamiento?','Buscar en la medida de mis fuerzas, aquello que sea útil a mi prójimo, de hacer con él lo que yo quisiera que él hiciese conmigo, y trabajar fielmente a fin de poder asistir a los necesitados en  su pobreza.','De la Ley','es',14,14,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(111,'¿Qué se pide en el noveno mandamiento?','Que no levante falsos testimonios contra nadie, que no interprete mal las palabras de los demás, que no sea ni detractor ni calumniador. Que no ayude a condenar a nadie temerari amente y sin haberle escuchado; que huya de toda clase de mentira y engaño como obras propias del diablo, si no quiero provocar contra mí la gravísima ira de Dios, Que en los juicios como en cualquier otra ocasión, ame la verdad, la anuncie y la confiese sinceramente, Y por último que procure con todas mis fuerzas defender la honra y reputación de mi prójimo.','De la Ley','es',14,14,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(112,'¿Qué ordena el décimo mandamiento?','Que ni por deseo o pensamiento nuestros corazones se rebelen jamás contra alguno de los mandamientos de Dios, sino que en todo tiempo aborrezcamos el pecado de todo corazón y nos deleitemos en toda justicia.','De la Ley','es',14,14,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(113,'¿Pueden guardar perfectamente estos mandamientos los que son convertidos a Dios?','No, porque incluso los más santos, en tanto estén en esta vida, no cumplen más que con un pequeño principio de esta obediencia. Sin embargo, empiezan a vivir firmemente no sólo según algunos, sino todos los mandamientos de Dios.','De la Ley','es',14,14,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(114,'Entonces, ¿Por qué quiere Dios que se nos predique tan rigurosamente los diez mandamientos, si no hay nadie que pueda observarlos perfectamente en esta vida?','Primeramente, para que durante toda nuestra vida conozcamos más y más, cuán grande es la inclinación de nuestra naturaleza a pecar, y así busquemos con más fervor la remisión de nuestros pecados y la justicia de Cristo. Después , que nos apliquemos sin descanso a suplicar a Dios la gracia de su Espíritu Santo, para que cada día seamos más renovados a su imagen, hasta que, después de esta vida, alcancemos la perfección que nos es propuesta.','De la Ley','es',14,14,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(115,'¿Por qué es necesaria la oración a los cristianos?','Porque es el punto principal de nuestro agradecimiento que Dios pide de nosotros, y porque El quiere dar su gracia y su Espíritu Santo sólo a aquellos que se lo piden con oraciones ardientes y continuas, dándole gracias.','Oración','es',14,14,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(116,'¿Qué es necesario en la oración para que ésta agrade a Dios y sea oída por Él?','Primero, que pidamos de todo corazón, al solo y verdadero Dios, el cual se ha manifestado en su palabra, todas las cosas que El desea que le pidamos. Segundo, que reconociendo sinceramente toda nuestra pobreza y miseria, nos humillemos delante de su majestad. Y por último que apoyándonos sobre este firme fundamento, sepamos que, pese a nuestra indignidad, El escuchará nuestra oración por amor del Señor Jesucristo, como nos lo ha prometido en su palabra.','Oración','es',15,15,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(117,'¿Qué nos ha mandado Dios que le pidamos?','Todo lo que es necesario para el alma y para el cuerpo, lo cual, nuestro Señor Jesucristo, ha incluido en la oración que él mismo nos ha enseñado.','Oración','es',15,15,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(118,'¿Qué dice esta oración?','Padre nuestro que estas en los cielos, santificado sea tu nombre. Venga tu reino. Sea hecha u voluntad, como en el cielo, así también en la tierra. Danos hoy nuestro pan cotidiano, y perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores. Y no nos metas en tentación, mas líbranos del mal. [Porque tuyo es el reino, y el poder, y la gloria, por todos los siglos. Amén.]','Oración','es',15,15,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(119,'¿Por qué nos pide nuestro Señor Jesucristo que nos dirijamos a Dios diciendo: "Padre nuestro?"','Para despertar en nosotros, desde el principio de nuestra oración, el respeto filial y la confianza en Dios que deben se elfundamento de nuestra oración. Es a saber, que Dios ha venido a ser nuestro Padre por Jesucristo, y nos concede con mayor seguridad las cosas que le pedimos con fe, que nuestros padres nos otorgan la cosas de este mundo.11','Oración','es',15,15,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(120,'¿Por qué se añade: Que estás en los cielos?','A fin de que no tengamos ninguna idea terrestre de la majestad celestial de Dios, y esperemos de su omnipotencia lo que necesitamos para nuestro cuerpo y nuestra alma.','Oración','es',15,15,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(121,'¿Cuál es la primera súplica?','Santificado sea tu nombre, es decir, concédenos ante todo que te conozcamos rectamente, y que santifiquemos y celebremos tu omnipotencia, sabiduría, bondad, justicia, misericordia y verdad, que se manifiestan en toda tus obras. Concédenos también, que toda nuestra vida, en pensamiento, palabra y obra, sea siempre dirigida a este fin: que tu santísimo nombre no sea por nosotros blasfemado ni menospreciado, sino honrado y glorificado.','Oración','es',15,15,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(122,'¿Cuál es su segunda súplica?','Venga tu reino, es decir; reina de tal modo sobre nosotros por tu Palabra y Espíritu, que nos sometamos cada vez más y más a Ti. Conserva y aumenta tu iglesia. Destruye las obras del diablo y todo poder que se levante contra Ti, lo mismo que todos los consejos que se toman contra tu Palabra, hasta que la plenitud de tu reino venga, cuando Tú serás todo en todos.','Oración','es',15,15,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(123,'¿Cuál es la tercera súplica?','Sea hecha tu voluntad, como en el cielo, así también en la tierra. Es decir, haz que nosotros y todos los hombres, renunciemos a nuestra propia voluntad, y con toda humildad obedezcamos la tuya que es la única buena, para que cada uno de nosotros cumpla su deber y vocación, tan fiel y gozosamente como lo hacen los ángeles en el cielo.','Oración','es',15,15,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(124,'¿Cuál es la cuarta súplica?','Danos hoy nuestro pan cotidiano, es decir, dígnate proveernos de todo lo que es necesario para el cuerpo, a fin de que, por ello reconozcamos que Tú eres la única fuente de todo bien, y que, ni nuestras necesidades, ni trabajo, ni incluso los bienes que Tú nos concedes, no nos aprovechan antes nos dañan sin tu bendición. Por tanto, concédenos que apartemos nuestra confianza de todas las criaturas, para ponerla sólo en Ti.','Oración','es',15,16,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(125,'¿Cuál es la quinta súplica?','Perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores; es decir: por la preciosa sangre de Jesucristo, dígnate no imputarnos, a nosotros pobres pecadores, nuestros pecados ni la maldad que está arraigada en nosotros, así como nosotros sentimos, por este testimonio de tu gracia, el firme propósito de perdonar de todo corazón a nuestro prójimo.','Oración','es',16,16,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(126,'¿Cuál es la sexta súplica?','No nos metas en tentación, más líbranos del mal; es decir, dado que nosotros mismos no podríamos subsistir un solo instante, y dado que, nuestros enemigos mortales como son: Satanás, el mundo y nuestra propia carne, nos hacen continua guerra; dígnate sostenernos y fortificarnos por la potencia de tu Espíritu Santo, para que podamos resistirles valerosamente, y no sucumbamos en ese combate espiritual, hasta que logremos finalmente la victoria.','Oración','es',16,16,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(127,'¿Cómo concluyes esta oración?','Porque tuyo es el reino, el poder, y la gloria, por todos los siglos. Esto es: Te pedimos todo esto, porque siendo nuestro Rey Todopoderoso, Tú puedes y quieres concedernos toda clase de bien, y esto para que, no a nosotros, sino a tu santo nombre sea todo gloria por todos los siglos.','Oración','es',16,16,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism" VALUES(128,'¿Qué significa la palabra: Amén? 12','Amén quiere decir: esto es verdadero y cierto. Porque mi oración es más ciertamente escuchada por Dios, que lo que yo siento en mi corazón, que he deseado de Él.','Oración','es',16,16,'heidelberg_catechism');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuál es tu único consuelo tanto en la vida como en la muerte?','Que yo, con cuerpo y alma, tanto en la vida como en la muerte, no me pertenezco a mí mismo, sino a mi fiel Salvador Jesucristo, que me libró del poder del diablo, satisfaciendo enteramente con preciosa sangre por todos mis pecados, y me guarda de tal manera que sin la voluntad de mi Padre celestial ni un solo cabello de mi cabeza puede caer antes es necesario que todas las cosas sirvan para mi salvación. Por eso también me asegura, por su Espíritu Santo, la vida eterna y me hace pronto y aparejado para vivir en adelante según su santa voluntad.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuántas cosas debes saber para que, gozando de esta consolación, puedas vivir y morir dichosamente?','Tres: La primera, cuán grande son mis pecados y miserias. La segunda, de qué manera puedo ser librado de ellos. Y la tercera, la gratitud que debo a Dios por su redención.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cómo conoces tu miseria?','Por la Ley de Dios.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué pide la Ley de Dios de nosotros?','Cristo nos enseñó sumariamente en Mateo cap. 22:37-40: Amarás al Señor tu Dios con todo tu corazón y con toda tu alma y con toda tu mente y con todas tus fuerzas. Este es el primero y grande mandamiento. Y el segundo es semejante: Amarás a tu prójimo como a ti mismo. De estos dos mandamientos depende toda la Ley y los Profetas.1','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Puedes cumplir todo esto perfectamente?','No, porque por naturaleza estoy inclinado a aborrecer a Dios y a mi prójimo.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Creó, pues, Dios al hombre tan malo y perverso?','No, al contrario. Dios creó al hombre bueno haciéndolo a su imagen y semejanza, es decir, en verdadera justicia y santidad,para que rectamente conociera a Dios su Creador, le amase de todo corazón y bienaventurado viviese con El eternamente, para alabarle y glorificarle.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿De dónde procede esta corrupción de la naturaleza humana?','De la caída y desobediencia de nuestros primeros padres Adán y Eva en el paraíso, por ello, nuestra naturaleza ha quedado de tal manera corrompida, que todos somos concebidos y nacidos en pecado.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Estamos tan corrompidos que somos totalmente incapaces de hacer el bien, e inclinados a todo mal?','Ciertamente; si no hemos sido regenerados por el Espíritu de Dios.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿No es Dios injusto con el hombre, al pedirle en su Ley que haga lo que no puede cumplir?','No, Dios creó al hombre en condiciones de poderla cumplir; pero el hombre por instigación del diablo y su propia rebeldía, se privó a sí y a toda su descendencia, de estos dones divinos.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Dejará Dios sin castigo, tal desobediencia y apostasía?','De ninguna manera; antes su ira se engrandece horriblemente, tanto por el pecado original, como por aquellos que cometemos ahora y quiere castigarlos, por su perfecta justicia, temporal o eternamente. Según ha dicho El mismo: Maldito todo aquel que no permaneciere en todas las cosas escritas en el libro de la Ley, para hacerlas.2','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('¿No es Dios también misericordioso?','Dios es misericordioso; pero también es justo. Por tanto su justicia exige que el pecado que se ha cometido contra su Suprema Majestad sea también castigado con el mayor castigo, que es pena eterna, así en el cuerpo como en el alma.','Introducción');
INSERT INTO "heidelberg_catechism_search" VALUES('Si por el justo juicio de Dios merecemos penas temporales y eternas, ¿No hay alguna posibilidad de liberarnos de estas penas y reconciliarnos con Dios?','Dios quiere que se dé satisfacción a su justicia: por eso es necesario que la satisfagamos eternamente por nosotros mismos o por algún otro.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Pero podemos satisfacerla por nosotros mismos?','De ninguna manera: antes acrecentamos cada día nuestra deuda.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Podría hallar ese alguien que siendo simple criatura pagase por nosotros?','No, Primero porque Dios no quiere castigar en otra criatura, la culpa de la cual el hombre es responsable, Segundo, porque una simple criatura es incapaz de soportar la ira eterna de Dios contra el pecado y liberar a otros de ella.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Entonces, que mediador y redentor debemos buscar?','Uno que sea el verdadero hombre y perfectamente justo y que sea más poderoso que todas las criaturas, es decir, que sea al mismo tiempo verdadero Dios.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué debe ser verdadero hombre y perfectamente justo?','Porque la justicia de Dios exige que la misma naturaleza humana que pecó, pague por el pecado; el hombre que es pecador, no puede pagar por otros.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué debe ser también verdadero Dios?','Para que, por la potencia de su divinidad, pueda llevar en su humanidad la carga de la ira de Dios, y reparar y restituir en nosotros la justicia y la vida.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('Mas ¿Quién es este mediador, que al mismo tiempo es verdadero Dios, y verdadero hombre perfectamente justo?','Nuestro Señor Jesucristo, el cual nos ha sido hecho por Dios, sabiduría y justicia, satisfacción y perfecta redención.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿De dónde sabes todo esto?','Del Santo Evangelio, del cual Dios reveló primeramente en el paraíso, y después lo anunció por los santos patriarcas y profetas, y lo hizo representar por los sacrificios y las demás ceremonias de la Ley: y al fin lo cumplió por su Hijo unigénito.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Son salvados por Cristo todos los hombres que perecieron en Adán?','No todos, sino sólo aquellos que por la verdadera fe son incorporados en El y aceptan sus beneficios.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué es la verdadera fe?','No es sólo un seguro conocimiento por el cual considero cierto todo lo que el Señor nos ha revelado en su palabra, sino también una verdadera confianza que el Espíritu Santo, infunde en mi corazón, por el Evangelio, dándome la seguridad, de que no sólo a otros sino también a mí mismo Dios otorga la remisión de pecados, la justicia y la vida eterna, y eso de pura gracia y solamente por los méritos de Jesucristo.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué es lo que debe creer el Cristiano?','Todo lo que se nos ha prometido en el Santo Evangelio, sumariamente contenido en el Símbolo Apostólico, en cuyos artículos se expresa la fe universal e infalible de todos los cristianos.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué dicen estos artículos?','Creo en Dios Padre, todopoderoso, Creador del cielo y de la tierra. Creo en Jesucristo su único hijo, nuestro Señor; que fue concebido por el Espíritu Santo, nació de María Virgen; padeció bajo el poder de Poncio Pilato, fue crucificado, muerto y sepultado; descendió a los infiernos, y al tercer día resucitó de entre los muertos; subió a los cielos; está sentado a la diestra de Dios, Padre todopoderoso, de donde vendrá a juzgar a los vivos y a los muertos. Creo en el espíritu Santo; una Santa Iglesia cristiana católica, la Comunión de los Santos; la remisión de los pecados, la resurrección del cuerpo y la vida eterna. Amén.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿En cuántas partes se dividen estos artículos?','En tres. La Primera: De Dios Padre y de nuestra creación. La Segunda: De Dios Hijo y de nuestra redención. La Tercera: De Dios Espíritu Santo y nuestra santificación.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('Si no hay más que una Esencia Divina, ¿Por qué nombras tres: Padre, Hijo y Espíritu Santo?','Porque Dios se manifestó así en su palabra, de manera que estas tres personas son el único, verdadero y eterno Dios.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué crees cuando dices: creo en Dios Padre Todopoderoso, creador del cielo y de la tierra?','Creo en el Padre de nuestro Señor Jesucristo, quien de la nada creó el cielo y de la tierra, con todo lo que en ellos hay, sustentándolo y gobernándolo todo por su eterno consejo y providencia, es mi Dios y mi Padre por amor de su hijo Jesucristo, En él confío de tal manera que no dudo de que me proveerá de todo lo necesario para mi alma y mi cuerpo. Y aún más, creo que todos los males que puedo sufrir por su voluntad, en este valle de lágrimas, los convertirá en bien para mi salvación. Él puede hacerlo como Dios todopoderoso, y quiere hacerlo como Padre benigno y fiel.','De Dios Padre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué es la providencia de Dios?','Es el poder de Dios omnipotente y presente en todo lugar, por el cual sustenta y gobierna el cielo, la tierra y todas las criaturas de tal manera, que todo lo que la tierra produce, la lluvia y la sequía, la fertilidad y la esterilidad, la comida y la bebida, la salud y la enfermedad, riquezas y pobrezas, y finalmente todas las cosas no acontecen sin razón alguna como por azar, sino por su consejo y voluntad paternal.','De Dios Padre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué utilidad tiene para nosotros este conocimiento de la creación y providencia divina?','Que en toda adversidad tengamos paciencia, y en la prosperidad seamos agradecidos, y tengamos puesta en el futuro, toda nuestra esperanza en Dios nuestro padre fidelísimo, sabiendo con certeza que no hay cosa que nos puede apartar de su amor, pues todas las criaturas, están sujetas a su poder de tal manera que no pueden hacer nada sin su voluntad.','De Dios Padre');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué el hijo de Dios es llamado Jesús, que significa Salvador?','Porque nos salva y libra de todos nuestros pecados, y porque en ningún otro se debe buscar ni se puede hallar salvación.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Creen pues también en el único Salvador Jesús, aquellos que buscan su salvación en los santos, o en sí mismos o en cualquiera otra parte?','No, porque aunque de boca se gloríen de tenerle por Salvador, de hecho niegan al único Salvador Jesús: pues necesariamente resulta, o que Jesús no es perfecto Salvador o que aquellos que con verdadera fe le reciben por Salvador tienen que poseer en El todo lo necesario para su salvación.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué se le llama Cristo, es decir: ungido?','Porque fue ordenado del Padre y ungido del Espíritu Santo, para ser nuestro supremo profeta y maestro, que nos ha revelado plenamente el secreto consejo y voluntad de Dios acerca de nuestra redención, para ser nuestro único y supremo pontífice quien por el sólo sacrificio de su cuer po nos ha redimido, e intercede continuamente delante del Padre por nosotros, para ser nuestro eterno Rey que nos gobierna por su palabra y su espíritu y nos guarda y conserva la redención que nos ha adquirido.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('Pues, ¿Porqué te llaman Cristiano?','Porque por la fe soy miembro de Jesucristo y participante de su unción, para que confiese su nombre y me ofrezca a Él, en sacrificio vivo y agradable y que en esta vida luche contra el pecado y Satanás con una conciencia limpia y buena y que, después de esta vida reine con Cristo eternamente sobre todas las criaturas.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué se llama a Cristo el unigénito hijo de Dios, si nosotros también somos hijos de Dios?','Porque Cristo es el hijo eterno y natural de Dios; pero nosotros hemos sido adoptados por gracia como hijos de Dios por amor de él.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué le llamamos nuestro Señor?','Por que rescatando nuestros cuerpos y almas de los pecados, no con oro o plata, sino con su preciosa sangre, y librándonos del poder del Diablo, nos ha hecho suyos.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué crees cuando dices: que fue concebido por el Espíritu santo y nació de María virgen?','Que el eterno Hijo de Dios, el cual es y permanece verdadero y eterno Dios, tomó la naturaleza verdaderamente humana de la carne y sangre de la virgen María, por obra del Espíritu Santo, para que juntamente fuese la verdadera simiente de David, semejante a sus hermanos excepto en el pecado.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué fruto sacas de la santa concepción y nacimiento de Cristo?','Que es nuestro Mediador, y con su inocencia y perfecta santidad cubre mis pecados en los cuales he sido concebido y nacido, para que no aparezcan en la presencia de Dios.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué es lo que crees cuando dices: padeció?','Que todo el tiempo que en este mundo vivió y especialmente al fin de su vida, sostenía en el cuerpo y el alma la ira de Dios contra el pecado de todo el género humano, para que con su pasión, como único sacrificio propiciatorio, librara nuestro cuerpo y alma de la eterna condenación, y nos alcanzase la gracia de Dios, la justicia y la vida eterna.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué padeció bajo el poder de Poncio Pilato juez?','Para que, inocente, condenado por el juez político, nos librase del severo juicio de Dios, que había de venir sobre nosotros.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Es más importante el haber sido crucificado, que morir de otro modo?','Sí, porque este género de muerte me garantiza que él cargó sobre sí mismo la maldición sentenciada sobre mí, por cuanto la muerte de cruz era maldita de Dios.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué fue necesario que Cristo se humillase hasta la muerte?','Porque la justicia de Dios no se podía satisfacer por nuestros pecados, sino con la misma muerte del Hijo de Dios.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué fue también sepultado?','Para testificar que estaba verdaderamente muerto.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('Ya que Cristo murió por nosotros, ¿Por qué hemos de morir también nosotros?','Nuestra muerte no es una satisfacción por nuestros pecados, sino una liberación del pecado y un paso hacia la vida eterna.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué provecho recibimos además del sacrificio y muerte de Cristo en la cruz?','Por su poder nuestro viejo hombre está crucificado, muerto y sepultado juntamente con Él, para que, en adelante, no reinen más en nosotros las perversas concupiscencias y deseos de la carne, sino que nos ofrezcamos a Él en sacrificio agradable.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué se añade: descendió a los infiernos?','Para que en mis extremados dolores y grandísimas tentaciones me asegure y me sostenga con este consuelo, de que mi Señor Jesucristo, por medio de las inexplicables angustias, tormentos, espantos y turbaciones infernales de su alma, en los cuales fue sumido en toda su pasión, pero especialmente clavado en la cruz, me ha librado de las ansias y tormentos del infierno.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué nos aprovecha la resurrección de Cristo?','Primero: Por su resurrección ha vencido a la muerte, para hacernos participantes de aquella justicia que conquistó por su muerte. Segundo: También nosotros somos resucitados ahora por su poder a una nueva vida. Tercero: la resurrección de Cristo, cabeza nuestra, es una cierta prenda de nuestra gloriosa resurrección.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué entiendes por: subió a los cielos?','Que Cristo, a la vista de sus discípulos, fue elevado de la tierra al cielo y que está allí para nuestro bien, hasta que vuelva a juzgar a los vivos y a los muertos.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('Luego, ¿No está Cristo con nosotros hasta el fin del mundo como lo prometido?.','Cristo es verdadero Dios y verdadero hombre: en cuanto a la naturaleza humana ahora ya no está en la tierra, pero en cuanto a su deidad, majestad, gracia y espíritu en ningún momen to está ausente de nosotros.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('Pero si la naturaleza humana no está en todas partes donde está la divina ¿No se separan con esto las dos naturalezas en Cristo?','De ninguna manera: porque dado que la divinidad es incomprensibley está presente en todo lugar, resulta necesariamente que en efecto está fuera de la naturalezahumana que ha tomado, perocon todo y con eso está en ella y queda unida a ella personalmente.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué beneficios nos da la ascensión de Cristo al cielo?','Primero: Él es nuestro intercesor en el cielo delante del Padre. Segundo: Que tenemos nuestra carne en el cielo para que por ello, como una garantía, estemos seguros, de que él siendo nuestra cabeza, nos atraerá a sí como miembros suyos. Tercero. Que desde allí nos envía su Espíritu como prenda recíproca, por cuya virtud buscamos, no las cosas de la tierra sino las de arriba, donde está sentado a la diestra de Dios.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué se añade: está sentado a la Diestra de Dios, Padre todopodero so?','PorqueCristo subió al cielo para mostrarse allí como cabeza de su Iglesia, por quien el Padre gobierna todas las cosas.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿De qué nos sirve esta gloria de Cristo, nuestra cabeza?','Primero: Para que el Espíritu Santo derrame en nosotros, sus miembros, los dones celestiales, y Segundo: Para protegernos y ampararnos de todos nuestros enemigos.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué consuelo te ofrece la vuelta de Cristo para juzgar a los vivos y a los muertos?','Que en todas las miserias y persecuciones, con plena confianza, espero del cielo como juez, a Aquel mismo que primeramente se puso delante del juicio de Dios por mí y alejó de mí toda maldición; el cual echará a todos los enemigos suyos y míos en las penas eternas; y a mí, con todos los elegidos, me conducirá al gozo del cielo y a la gloria eterna.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué crees del Espíritu Santo?','Que con el Eterno Padre e Hijo, es verdadero y eterno Dios. Y que viene a morar en mí para que, por la verdadera fe, me haga participante de Cristo y de todos sus beneficios, me consuele y quede conmigo eternamente.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué crees de la santa Iglesia cristiana católica?','Que el Hijo de Dios, desde el principio hasta el fin del mundo, de todo el género humano, congrega, guarda y protege para sí, por su Espíritu y su palabra en la unidad de la verdadera fe, una comunidad, elegida para la vida eterna; de la cual yo soy un miembro vivo y permaneceré para siempre.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué entiendes por la comunión de los santos?','Primero, que todos los fieles en general y cada uno en particular, como miembros del Señor Jesucristo, tienen la comunión de Él y de todos sus bienes y dones. Segundo, que cada uno debe sentirse obligado a emplear con amor y gozo los dones que ha recibido, utilizándolos en beneficio de los demás.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué crees de la remisión de los pecados?','Creo que Dios, por la satisfacción de Cristo, no quiere acordarse jamás de mis pecados, ni de mi naturaleza corrompida, con la cual debo luchar toda la vida, sino que gratuitamente me otorga la justicia de Cristo para que yo nunca venga a condenación.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué consuelo te da la resurrección de la carne?','Que no sólo mi alma después de esta vida será llevada en el mismo instante a Cristo, su cabeza, sino que también está mi carne, siendo resucitada por la potencia de Cristo, será de nuevo unida a mi alma y hecha conforme al glorioso cuerpo de Cristo.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué consolación te ofreceel artículo de la vida eterna?','Que ahora siento en mi corazón un principio de la vida eterna, después de esta vida, gozaré de una cumplida y perfecta bienaventuranza que ningún ojo vio ni oído oyó, ni entendimiento humano comprendió, y esto para que ella alabe a Dios para siempre ( b).','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué te aprovecha el creer en todas estas cosas?','Que delante de Dios soy justo en Jesucristo,y heredero de la vida eterna.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cómo eres justo ante Dios?','Por la sola verdadera fe en Jesucristo, de tal suerte que, aunque mi conciencia me acuse de haber pecado gravemente contra todos los mandamientos de Dios, no habiendo guardado jamás ninguno de ellos,y estando siempre inclinado a todo mal, sin merecimiento alguno mío, sólo por su gracia, Dios me imputa y da la perfecta satisfacción, justicia y santidad de Cristo como si no hubiera yo tenido, ni cometido algún pecado, antes bien como si yo mismo hubiera cumplido aquella obediencia que Cristo cumplió por mí, con tal que yo abrace estas gracias y beneficios con verdadera fe.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué afirmas ser justo sólo por la fe?','No porque agrade a Dios por la dignidad de mi fe, sino porque sólo la satisfacción, justicia y santidad de Cristo, son mi propia justicia delante de Dios, y que yo no puedo cumplir de otro modo que por la fe.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué no pueden justificarnos ante Dios las buenas obras, aunque sólo sea una parte?','Porque es necesario que aquella justicia, que ha de aparecer delante del juicio de Dios, sea perfectamente cumplida y de todo punto conforme a la Ley Divina; y nuestras buenas obras, aun las mejores en esta vida, son imperfectas y contaminadas de pecado.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('Luego, ¿Cómo es posible que nuestras obras no merezcan nada, si Dios promete remunerarlas en la vida presente y en la venidera?','Esta remuneración no se da por merecimiento, sino por gracia.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('Pero esta doctrina, ¿no hace a los hombres negligentes e impíos?','No, porque es imposible que no produzcan frutos de gratitud los que por la fe verdadera han sido injertados en Cristo.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('Si sólo la fe nos hace participantes de Cristo y de todos sus beneficios, dime, ¿de dónde procede esta fe?','Del Espíritu Santo que la hace obrar por la predicación del Santo Evangelio, encendiendo nuestros corazones, y confirmándola por el uso de los sacramentos.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué son los Sacramentos?','Son señales sagradas y visibles, y sellos instituidos por Dios, para sernos declarada mejor y sellada por ellos la promesa del Evangelio; a saber, que la remisión de los pecados y la vida eterna, por aquel único sacrificio de Cristo cumplido en la cruz, se nos da de gracia no solamente a todos los creyentes en general, sino también a cada uno en particular.','De los Sacramentos');
INSERT INTO "heidelberg_catechism_search" VALUES('Entonces la palabra y los Sacramentos ¿tienen como fin llevar nuestra fe al sacrificio de Cristo cumplido en la cruz, como el único fundamento de nuestra salvación?','Así es, porque el Espíritu Santo nos enseña por el Evangelio y confirma por los Sacramentos, que toda nuestra salud está puesta en el único sacrificio de Cristo ofrecido por nosotros en la cruz.','De los Sacramentos');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuántos sacramentos ha instituido Cristo en el Nuevo Testamento?','Dos: El Santo Bautismo y la Santa Cena.','De los Sacramentos');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué el Santo bautismo te asegura y recuerda que eres participante de aquel único sacrificio de Cristo, hecho en la Cruz?','Porque Cristo ha instituido, el lavamiento exterior del agua, añadiendo esta promesa, que tan ciertamente soy lavado con su sangre y Espíritu de las inmundicias de mi alma, es a saber, de todos mis pecados, como soy rociado y lavado exteriormente con el agua, con la cual se suelen limpiar las suciedades del cuerpo.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué es ser lavado con la sangre y el Espíritu de Cristo?','Es recibir de la gracia de Dios, la remisión de los pecados, por la sangre de Cristo, que derramó por nosotros en su sacrificio en la Cruz. Y también ser renovados y santificados por el Espíritu Santo, para ser miembros de Cristo, a fin de que muramos al pecado y vivamos santa e irreprensiblemente.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Dónde prometió Cristo que Él nos quiere limpiar tan ciertamente por su sangre y Espíritu como somos lavados por el agua del bautismo?','En la institución del Bautismo, cuyas palabras son éstas: "Id, enseñad a todas las gentes, bautizándolas en el nombre del Padre y del Hijo, y del Espíritu Santo" (Mateo 28:19) 3 "El que creyere y fuere bautizado, será salvo; mas el que no creyere, será condenado" (Marcos 16:16). 4 Esta misma promesa se repite cuando las Sagradas escrituras llaman al bautismo "lavamiento de la regeneración y ablución de pecados" (Tito 3:5, Hechos 22:16).5','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Es el lavamiento, la purificación misma de los pecados?','No: porque sólo la sangre de Jesucristo y el Espíritu Santo nos limpia y purifica de todo pecado.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search" VALUES('Entonces, ¿Por qué llama el Espíritu Santo al bautismo el lavado de la regeneración y la purificación de los pecados?','Dios no habla así sin una razón justificada, pues Él, no sólo quiere enseñarnos que nuestros pecados se purifican por la sangre y el Espíritu de Cristo, como las suciedades del cuerpo por el agua, sino más aún: certificarnos por este divino símbolo y prenda que verdaderamente somos limpiados por el lavamiento interior y espiritual de nuestros pecados, de la misma manera que somos lavados exteriormente por el agua visible.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Se ha de bautizar también a los niños?','Naturalmente, porque están comprendidos, como los adultos, en el pacto, y pertenecen a la iglesia de Dios. Tanto a éstos como a los adultos se les promete por la sangre de Cristo, la remisión de los pecados y el Espíritu Santo, obrador de la fe; por esto, y como señal de este pacto, deben ser incorporados a la Iglesia de Dios y diferenciados de los hijos de los infieles, así como se hacía en el pacto del Antiguo Testamento por la circuncisión, cuyo sustito es el Bautismo en el Nuevo Pacto.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cómo te asegura y confirma la Santa Cena que eres hecho participante de aquel único sacrificio de Cristo, ofrecido en la cruz, y de todos sus bienes?','Porque Cristo me ha mandado, y también a todos los fieles, comer de este pan partido y beber de esta copa en memoria suya, añadiendo esta promesa: Primero, que su cuerpo ha sido ofrecido y sacrificado por mí en la cruz, y su sangre derramada por mis pecados, tan cierto como que veo con mis ojos que el pan del Señor es partido para mí y que me es ofrecida la copa. Y Segundo, que El tan cierto alimenta mi alma para la vida eterna con su cuerpo crucificado y con su sangre derramada, como yo recibo con la boca corporal de la mano del ministro el pan y el vino, símbolos del cuerpo y de la sangre del Señor.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué significa comer el cuerpo sacrificado de Cristo y beber su sangre derramada?','Significa, no sólo abrazar con firme confianza del alma toda la pasión y muerte de Cristo, y por este medio alcanzar la remisión de pecados y la vida eterna, sino unirse más y más a su santísimo cuerpo por el Espíritu Santo, el cual habita juntamente en Cristo y en nosotros de tal manera, que, aunque El esté en el cielo y nosotros en la tierra, todavía somos carne de su carne y huesos de sus huesos, y que, de un mismo espíritu, (como todos los miembros del cuerpo por una sola alma) somos vivificados y gobernados para siempre.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Dónde prometió Cristo, que tan ciertamente dará a los creyentes en comida y en bebida su cuerpo y sangre, como comen de este pan roto y beben de este vaso?','En la institución de la cena, cuyas palabras fueron: Nuestro Señor Jesucristo, la noche que fue entregado, tomó el pan, y habiendo dado gracias, lo partió y dijo: Tomad, comed, esto es mi cuerpo que por vosotros es partido; haced en memoria de mí. Asimismo tomó también la copa, después de haber cenado, diciendo: Esta copa es el nuevo pacto en mi sangre;haced esto todas las veces que la bebereis, en memoria de mí. Así, pues, todas las veces que comiereis este pan y bebiereis esta copa, la muerte del Señor anunciáis hasta que él venga (1 Cor. 11:23-26).6 Pablo repite esta promesa cuando dice: La copa de bendición, que bendecimos, ¿no es la comunión de la sangre de Cristo?, El pan que partimos, ¿no es la comunión del cuerpo de Cristo? Siendo uno solo el pan, nosotros, con ser muchos, somos un cuerpo: pues todos participamos de aquel mismo pan (1 Cor. 10:16,17).7','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿El pan y el vino se convierten sustancialmente en el mismo cuerpo y sangre de Cristo?','De ninguna manera, pues como el agua del Bautismo no se convierte en la sangre de Cristo, ni es la misma ablución de los pecados, sino solamente una señal y sello de aquellas cosas que nos son selladas en el Bautismo, así el pan de la Cena del Señor no es el mismo cuerpo, aunque por la naturaleza y uso de los sacramentos es llamado el cuerpo de Cristo.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué llama Cristo al pan su cuerpo y a la copa su sangre, o el Nuevo Testamento en su sangre, y Pablo al pan y al vino la comunión del cuerpo y sangre de Cristo?','Cristo no habla así sin una razón poderosa, y no solamente para enseñarnos que, así como el pan y el vino sustentan la vida corporal, su cuerpo crucificado y su sangre derramada son la verdadera comida y bebida, que alimentan nuestras almas para la vida eterna, más aún, para asegurarnos por estas señales y sellos visibles, que por obra del Espíritu Santo somos participantes de su cuerpo y sangre tan cierto como que tomamos estos sagrados símbolos en su memoria y por la boca del cuerpo; y también que su pasión y obediencia son tan ciertamente nuestras ,como si nosotros mismos en nuestras personas hubiéramos sufrido la pena y satisfecho a Dios por nuestros pecados.8','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Quiénes son los que deben participar de la mesa del Señor?','Tan sólo aquellos que se duelan verdaderamente de haber ofendido a Dios con sus pecados, confiando en ser perdonados por el amor de Cristo y que las demás flaquezas quedarán cubiertas con su pasión y muerte. Y que también deseen fortalecer más y más su fe y mejorar su vida. Pero los hipócritas y los que no se arrepienten de verdad, comen y beben su condenación.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Deben admitirse también a esta Cena, los que por su confesión y vida se declaran infieles e impíos?','De ninguna manera, porque así se profana el pacto de Dios, y se provoca su ira sobre toda la congregación. Por lo cual, la Iglesia debe, según la orden de Cristo y de sus apóstoles (usando de las llaves del reino de los cielos), excomulgar y privar a los tales de la Cena, hasta que se arrepientan y rectifiquen su vida.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué son las llaves del reino de los cielos?','La predicación del Santo Evangelio y la disciplina eclesiástica: con los cuales se abre el cielo a los fieles, y se cierra a los infieles.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿De qué manera se abre y se cierra el reino de los cielos por la predicación del Evangelio?','Cuando (según el mandamiento de Cristo) públicamente es anunciado y testificado a todos los fieles en general y a cada uno en particular, que todos los pecados les son perdonados por Dios, por los méritos de Cristo, todas las veces que abrazaren con verdadera fe la promesa del evangelio. Al contrario, a todos los infieles e hipócritas, se les anuncia que la ira de Dios y la condenación eterna  caerá sobre ellos mientras perseveraren en su maldad; según testimonio del Evangelio, Dios juzgará así en esta vida como en la otra.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('¿De qué manera se cierra y se abre el reino de los cielos por la disciplina eclesiástica?','Cuando (según el mandamiento de Cristo) aquellos que bajo el nombre de cristianos se muestran en la doctrina o en la vida ajenos a Cristo, y después de haber sido fraternalmente amonestados en diversas ocasiones, no quieren apartarse de sus errores o maldades, son denunciados a la Iglesia o a los que han sido amonestados por ella. Y si aun no obedecen a la amonestación de éstos, por la prohibición de los sacramentos, son expulsados de la congregación cristiana, y por el mismo Dios, del reino de Cristo; y otra vez recibidos, como miembros de Cristo y de su Iglesia, cuando prometen enmienda y lo demuestran por sus obras.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search" VALUES('Si somos liberados por Cristo de todos nuestros pecados y miserias sin merecimiento alguno de nuestra parte, sino sólo por la misericordia de Dios ¿Por qué hemos de hacer buenas obras?','Porque después de que Cristo nos ha redimido con su sangre, nos renueva también con su Espíritu Santo a su imagen; a fin de que en toda nuestra vida nos mostremos agradecidos a Dios por tantos beneficios y que Él sea glorificado por nosotros. Además de esto para que cada uno de nosotros sea asegurado de su fe por los frutos. Y finalmente para que, también por la piedad e integridad de nuestra vida, ganemos a nuestro prójimo para Cristo.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search" VALUES('Luego, ¿No pueden salvarse aquellos que siendo desagradecidos y perseverando en sus pecados no se conviertan a Dios de su maldad?','De ninguna manera, porque, como lo testifican las Sagradas Escrituras, no herederán el reino de Dios los fornicarios, los idólatras, los adúlteros, los ladrones, los avaros, los borrachos, los maldicientes.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search" VALUES('¿De cuantas partes se compone el verdadero arrepentimiento y conversión al Señor?','De dos: la muerte del viejo hombre, y la vivificación del nuevo.9','De la Gratitud');
INSERT INTO "heidelberg_catechism_search" VALUES('¿En qué consiste la muerte del hombre viejo?','En que sintamos pesar, de todo corazón, de haber ofendido a Dios con nuestros pecados, aborreciéndolos y evitándolos.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué es la vivificación del nuevo hombre?','Es alegrarse de todo corazón en Dios por Cristo, y desear vivir conforme a la voluntad de Dios, así como ejercitarse en toda buena obra.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué son las buenas obras?','Únicamente aquellas que se realizan con fe verdadera, conforme a la Ley de Dios, y se aplican solamente a su gloria; y no aquellas que están fundadas en nuestras buenas intenciones o sobre instituciones humanas.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuál es la Ley de Dios?','Y habló Dios todas estas palabras (Éxodo 20:1-17): PRIMER MANDAMIENTO: No tendrás dioses ajenos delante de mí. SEGUNDO MANDAMIENTO: No te harás imagen, ni ninguna semejanza de lo que esté arriba en el cielo, ni abajo en la tierra, ni en las aguas debajo de la tierra, No te inclinarás a ellas, ni las honrarás; porque yo soy Jehová tu Dios, fuerte, celoso, que visitó la maldad de los padres sobre los hijos, hasta la tercera y cuarta generación, de los que me aborrecen; y hago misericordia a millares, a los que me aman y guardan mis mandamientos. TERCER MANDAMIENTO: No tomarás el nombre de Jehová tu Dios en vano; porque no dará por inocente Jehová al que tomare su nombre en vano. CUARTO MANDAMIENTO: Acuérdate del día de reposo para santificarlo; seis días trabajarás, y harás toda su obra; mas el séptimo día es de reposo para Jehová tu Dios; no hagas en él obra alguna, tú ni tu hijo, ni tu hija ni tu siervo ni tu criada ni tu bestia, ni tu extranjero que está dentro de tus puertas. Porque en seis días hizo Jehová los cielos y la tierra, el mar y todas las cosas que en ellos hay, y reposó en el séptimo día; por tanto, Jehová bendijo el día de reposo y lo santificó. QUINTO MANDAMIENTO: Honra a tu padre y a tu madre, para que tus días se alarguen en la tierra que Jehová tu Dios te da. SEXTO MANDAMIENO: No matarás. SEPTIMO MANDAMIENO: No cometerás adulterio. OCTAVO MANDAMIENTO: No hurtarás. NOVENO MANDAMIENTO: No hablarás contra tu prójimo falso testimonio. DECIMO MANDAMIENTO: No codiciarás la casa de tu prójimo, no codiciarás la mujer de tu prójimo ni su siervo, ni su criada, ni su buey, ni su asno, ni cosa alguna de tu prójimo.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cómo se dividen estos diez mandamientos?','En dos tablas: De las cuales la primera enseña lo que debemos hacer para con Dios; la segunda, lo que debemos hacer para con nuestro prójimo.10','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué manda Dios en el primer mandamiento?','Que yo, que deseo la salvación de mi alma, evite y huya de toda idolatría, hechicería, encantamiento, superstición, invocación de santos y de otras criaturas; y que conozca rectamente al único verdadero Dios, en El sólo confié con toda humildad y paciencia, a El que de todo corazónle ame, tema y reverencie; de tal manera que esté dispuesto a renunciar a todas las criaturas antes que cometer la menor cosa contra su voluntad.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué es idolatría?','Es poner en el lugar que sólo corresponde al Dios verdadero que se ha revelado por su Palabra, o junto a Él, cualquier otra cosa en la cual se ponga confianza.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué pide Dios en el segundo mandamiento?','Que no representemos a Dios por medio de alguna imagen o figura, y sólo le rindamos culto como Él ha mandado en su Palabra.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿No es lícito hacer ninguna imagen?','Ni podemos, ni debemos representar a Dios de ninguna manera, y aun en el caso de que fuese lícito representar a las criaturas, Dios prohíbe hacer o poseer ninguna imagen destinada a ser adorada o empleada en su servicio.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿No se podrían tolerar las imágenes en las iglesias, como si fuesen libros para enseñar a los ignorantes?','No, porque nosotros no debemos ser más sabios que Dios, que no quiere instruir a su pueblo por imágenes mudas, sino por la predicación viva de su Palabra.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué nos enseña el tercer mandamiento?','Que dejemos de blasfemar o profanar el nombre de Dios por medio de falsos juramentos y maldiciones, y aún inútiles juramentos; que no nos hagamos partícipes de tan horrendos pecados al callar cuando los oigamos. En una palabra: que no empleemos el santo nombre de Dios , mas que con temor y veneración, a fin de que Él sea rectamente confesado, invocado y glorificado por nuestras palabras y hechos.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Es tan grave pecado el profanar el nombre de Dios por medio de juramentos y blasfemias, que Dios también se enoja contra aquellos que no se opusieron y no lo prohibieron con todas sus fuerzas?','Sí, porque no hay mayor pecado ni cosa que a Dios más ofenda que el profanar su nombre, por lo cual mandó que esta maldad fuese castigada con la muerte.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Se puede jurar santamente en nombre de Dios?','Sí, cuando el magistrado o la necesidad así lo exijan para sostener y confirmar la fe y la verdad, para la gloria de Dios y el bien de nuestro prójimo. Pues tal manera de prestar juramento está fundada en la palabra de Dios y, en consecuencia, ha sido rectamente empleada por los santos, tanto en el Antiguo como en el Nuevo Testamento.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Es lícito jurar por los santos u otras criaturas?','No. Porque el legítimo juramento es una invocación de Dios, por la cual se le pide, que Él, como el que sólo ve los corazones, sea testigo de la verdad, y castigue si el juramento es falso; este honor le corresponde a Él.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué ordena Dios en el cuarto mandamiento?','Primero, que el ministerio de la Palabra y la enseñanza sean mantenidos, y que yo frecuente asiduamente la iglesia, la congregación de Dios, sobre todo el día de reposo, para oír la Palabra de Dios, y participar de los santos sacramentos, para invocar públicamente al Señor, y para contribuir cristianamente a ayudar a los necesitados. Además, que todos los días de mi vida cese de mal obrar, para que sea Dios mismo quien obre en mi corazón por su Espíritu, y de este modo pueda empezar en esta vida el Sábado eterno.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué manda Dios en el quinto mandamiento?','Que muestre a mi padre y a mi madre y a todos mis superiores, honor, amor y fidelidad, que me someta obedientemente a sus buenas enseñanzas y castigos, soportando  también pacientemente sus flaquezas, pues Dios quiere regirnos por medio de ellos.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué exige Dios en el sexto mandamiento?','Que ni por mis pensamientos, palabras, actitud y aún menos por mis actos, por mí mismo o por medio de otro, llegue a injuriar, odiar, ofender o matar a mí prójimo, por el contrario que, renuncie a todo deseo de venganza; que no me haga mal a mi mismo o me exponga temerariamente al peligro. Para impedir esto, el magistrado posee la espada.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Este mandamiento sólo prohíbe matar?','Al prohibir la muerte Dios nos enseña que Él detesta todo lo que de ello se origina, como la envidia, el odio, la ira y el deseo de venganza, considerando todo esto como verdadero homicidio.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Es suficiente, como hemos dicho, el no matar a nuestro prójimo?','No; pues Dios, condenando la envidia, el odio y la ira, quiere que amemos a nuesro prójimo como a nosotros mismos, usando para con él toda benignidad, mansedumbre, paciencia y misericordia, impidiendo hasta donde nos sea posible,el mal que le podría sobrevenir, haciendo bien incluso a nuestros enemigos.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué enseña el séptimo mandamiento?','Que Dios maldice toda deshonestidad, y en consecuencia nosotros debemos también aborrecerla de todo corazón y vivir casta y sobriamente, sea en el santo estado de matrimonio, o en otro estado.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿En este mandamiento, prohíbe sólo Dios el adulterio y pecados semejantes?','Como nuestro cuerpo y alma son templo del Espíritu Santo, Dios quiere que conservemos ambos puros y santos.Para ello prohíbe toda impureza en nuestras acciones, nuestros gestos, nuestras palabras, nuestros pensamientos y deseos, y todo lo que incita al hombre a ello.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué prohíbe Dios en el octavo mandamiento?','Dios prohíbe no solamente el robo y la rapiña que castiga la autoridad , sino que llama también robo a todos los medios malos y engaños con los cuales tratamos de apoderarnos del bien de nuestro prójimo, ya sea por la fuerza por una apariencia de derecho, como son: el peso falso,la mala mercadería, la moneda falsa, la usura, o por cualquier otro medio prohibido por Dios. También prohíbe toda avaricia y todo uso inútil de sus dones.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué te ordena Dios en este mandamiento?','Buscar en la medida de mis fuerzas, aquello que sea útil a mi prójimo, de hacer con él lo que yo quisiera que él hiciese conmigo, y trabajar fielmente a fin de poder asistir a los necesitados en  su pobreza.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué se pide en el noveno mandamiento?','Que no levante falsos testimonios contra nadie, que no interprete mal las palabras de los demás, que no sea ni detractor ni calumniador. Que no ayude a condenar a nadie temerari amente y sin haberle escuchado; que huya de toda clase de mentira y engaño como obras propias del diablo, si no quiero provocar contra mí la gravísima ira de Dios, Que en los juicios como en cualquier otra ocasión, ame la verdad, la anuncie y la confiese sinceramente, Y por último que procure con todas mis fuerzas defender la honra y reputación de mi prójimo.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué ordena el décimo mandamiento?','Que ni por deseo o pensamiento nuestros corazones se rebelen jamás contra alguno de los mandamientos de Dios, sino que en todo tiempo aborrezcamos el pecado de todo corazón y nos deleitemos en toda justicia.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Pueden guardar perfectamente estos mandamientos los que son convertidos a Dios?','No, porque incluso los más santos, en tanto estén en esta vida, no cumplen más que con un pequeño principio de esta obediencia. Sin embargo, empiezan a vivir firmemente no sólo según algunos, sino todos los mandamientos de Dios.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('Entonces, ¿Por qué quiere Dios que se nos predique tan rigurosamente los diez mandamientos, si no hay nadie que pueda observarlos perfectamente en esta vida?','Primeramente, para que durante toda nuestra vida conozcamos más y más, cuán grande es la inclinación de nuestra naturaleza a pecar, y así busquemos con más fervor la remisión de nuestros pecados y la justicia de Cristo. Después , que nos apliquemos sin descanso a suplicar a Dios la gracia de su Espíritu Santo, para que cada día seamos más renovados a su imagen, hasta que, después de esta vida, alcancemos la perfección que nos es propuesta.','De la Ley');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué es necesaria la oración a los cristianos?','Porque es el punto principal de nuestro agradecimiento que Dios pide de nosotros, y porque El quiere dar su gracia y su Espíritu Santo sólo a aquellos que se lo piden con oraciones ardientes y continuas, dándole gracias.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué es necesario en la oración para que ésta agrade a Dios y sea oída por Él?','Primero, que pidamos de todo corazón, al solo y verdadero Dios, el cual se ha manifestado en su palabra, todas las cosas que El desea que le pidamos. Segundo, que reconociendo sinceramente toda nuestra pobreza y miseria, nos humillemos delante de su majestad. Y por último que apoyándonos sobre este firme fundamento, sepamos que, pese a nuestra indignidad, El escuchará nuestra oración por amor del Señor Jesucristo, como nos lo ha prometido en su palabra.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué nos ha mandado Dios que le pidamos?','Todo lo que es necesario para el alma y para el cuerpo, lo cual, nuestro Señor Jesucristo, ha incluido en la oración que él mismo nos ha enseñado.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué dice esta oración?','Padre nuestro que estas en los cielos, santificado sea tu nombre. Venga tu reino. Sea hecha u voluntad, como en el cielo, así también en la tierra. Danos hoy nuestro pan cotidiano, y perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores. Y no nos metas en tentación, mas líbranos del mal. [Porque tuyo es el reino, y el poder, y la gloria, por todos los siglos. Amén.]','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué nos pide nuestro Señor Jesucristo que nos dirijamos a Dios diciendo: "Padre nuestro?"','Para despertar en nosotros, desde el principio de nuestra oración, el respeto filial y la confianza en Dios que deben se elfundamento de nuestra oración. Es a saber, que Dios ha venido a ser nuestro Padre por Jesucristo, y nos concede con mayor seguridad las cosas que le pedimos con fe, que nuestros padres nos otorgan la cosas de este mundo.11','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Por qué se añade: Que estás en los cielos?','A fin de que no tengamos ninguna idea terrestre de la majestad celestial de Dios, y esperemos de su omnipotencia lo que necesitamos para nuestro cuerpo y nuestra alma.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuál es la primera súplica?','Santificado sea tu nombre, es decir, concédenos ante todo que te conozcamos rectamente, y que santifiquemos y celebremos tu omnipotencia, sabiduría, bondad, justicia, misericordia y verdad, que se manifiestan en toda tus obras. Concédenos también, que toda nuestra vida, en pensamiento, palabra y obra, sea siempre dirigida a este fin: que tu santísimo nombre no sea por nosotros blasfemado ni menospreciado, sino honrado y glorificado.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuál es su segunda súplica?','Venga tu reino, es decir; reina de tal modo sobre nosotros por tu Palabra y Espíritu, que nos sometamos cada vez más y más a Ti. Conserva y aumenta tu iglesia. Destruye las obras del diablo y todo poder que se levante contra Ti, lo mismo que todos los consejos que se toman contra tu Palabra, hasta que la plenitud de tu reino venga, cuando Tú serás todo en todos.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuál es la tercera súplica?','Sea hecha tu voluntad, como en el cielo, así también en la tierra. Es decir, haz que nosotros y todos los hombres, renunciemos a nuestra propia voluntad, y con toda humildad obedezcamos la tuya que es la única buena, para que cada uno de nosotros cumpla su deber y vocación, tan fiel y gozosamente como lo hacen los ángeles en el cielo.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuál es la cuarta súplica?','Danos hoy nuestro pan cotidiano, es decir, dígnate proveernos de todo lo que es necesario para el cuerpo, a fin de que, por ello reconozcamos que Tú eres la única fuente de todo bien, y que, ni nuestras necesidades, ni trabajo, ni incluso los bienes que Tú nos concedes, no nos aprovechan antes nos dañan sin tu bendición. Por tanto, concédenos que apartemos nuestra confianza de todas las criaturas, para ponerla sólo en Ti.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuál es la quinta súplica?','Perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores; es decir: por la preciosa sangre de Jesucristo, dígnate no imputarnos, a nosotros pobres pecadores, nuestros pecados ni la maldad que está arraigada en nosotros, así como nosotros sentimos, por este testimonio de tu gracia, el firme propósito de perdonar de todo corazón a nuestro prójimo.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cuál es la sexta súplica?','No nos metas en tentación, más líbranos del mal; es decir, dado que nosotros mismos no podríamos subsistir un solo instante, y dado que, nuestros enemigos mortales como son: Satanás, el mundo y nuestra propia carne, nos hacen continua guerra; dígnate sostenernos y fortificarnos por la potencia de tu Espíritu Santo, para que podamos resistirles valerosamente, y no sucumbamos en ese combate espiritual, hasta que logremos finalmente la victoria.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Cómo concluyes esta oración?','Porque tuyo es el reino, el poder, y la gloria, por todos los siglos. Esto es: Te pedimos todo esto, porque siendo nuestro Rey Todopoderoso, Tú puedes y quieres concedernos toda clase de bien, y esto para que, no a nosotros, sino a tu santo nombre sea todo gloria por todos los siglos.','Oración');
INSERT INTO "heidelberg_catechism_search" VALUES('¿Qué significa la palabra: Amén? 12','Amén quiere decir: esto es verdadero y cierto. Porque mi oración es más ciertamente escuchada por Dios, que lo que yo siento en mi corazón, que he deseado de Él.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(1,'¿Cuál es tu único consuelo tanto en la vida como en la muerte?','Que yo, con cuerpo y alma, tanto en la vida como en la muerte, no me pertenezco a mí mismo, sino a mi fiel Salvador Jesucristo, que me libró del poder del diablo, satisfaciendo enteramente con preciosa sangre por todos mis pecados, y me guarda de tal manera que sin la voluntad de mi Padre celestial ni un solo cabello de mi cabeza puede caer antes es necesario que todas las cosas sirvan para mi salvación. Por eso también me asegura, por su Espíritu Santo, la vida eterna y me hace pronto y aparejado para vivir en adelante según su santa voluntad.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(2,'¿Cuántas cosas debes saber para que, gozando de esta consolación, puedas vivir y morir dichosamente?','Tres: La primera, cuán grande son mis pecados y miserias. La segunda, de qué manera puedo ser librado de ellos. Y la tercera, la gratitud que debo a Dios por su redención.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(3,'¿Cómo conoces tu miseria?','Por la Ley de Dios.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(4,'¿Qué pide la Ley de Dios de nosotros?','Cristo nos enseñó sumariamente en Mateo cap. 22:37-40: Amarás al Señor tu Dios con todo tu corazón y con toda tu alma y con toda tu mente y con todas tus fuerzas. Este es el primero y grande mandamiento. Y el segundo es semejante: Amarás a tu prójimo como a ti mismo. De estos dos mandamientos depende toda la Ley y los Profetas.1','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(5,'¿Puedes cumplir todo esto perfectamente?','No, porque por naturaleza estoy inclinado a aborrecer a Dios y a mi prójimo.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(6,'¿Creó, pues, Dios al hombre tan malo y perverso?','No, al contrario. Dios creó al hombre bueno haciéndolo a su imagen y semejanza, es decir, en verdadera justicia y santidad,para que rectamente conociera a Dios su Creador, le amase de todo corazón y bienaventurado viviese con El eternamente, para alabarle y glorificarle.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(7,'¿De dónde procede esta corrupción de la naturaleza humana?','De la caída y desobediencia de nuestros primeros padres Adán y Eva en el paraíso, por ello, nuestra naturaleza ha quedado de tal manera corrompida, que todos somos concebidos y nacidos en pecado.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(8,'¿Estamos tan corrompidos que somos totalmente incapaces de hacer el bien, e inclinados a todo mal?','Ciertamente; si no hemos sido regenerados por el Espíritu de Dios.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(9,'¿No es Dios injusto con el hombre, al pedirle en su Ley que haga lo que no puede cumplir?','No, Dios creó al hombre en condiciones de poderla cumplir; pero el hombre por instigación del diablo y su propia rebeldía, se privó a sí y a toda su descendencia, de estos dones divinos.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(10,'¿Dejará Dios sin castigo, tal desobediencia y apostasía?','De ninguna manera; antes su ira se engrandece horriblemente, tanto por el pecado original, como por aquellos que cometemos ahora y quiere castigarlos, por su perfecta justicia, temporal o eternamente. Según ha dicho El mismo: Maldito todo aquel que no permaneciere en todas las cosas escritas en el libro de la Ley, para hacerlas.2','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(11,'¿No es Dios también misericordioso?','Dios es misericordioso; pero también es justo. Por tanto su justicia exige que el pecado que se ha cometido contra su Suprema Majestad sea también castigado con el mayor castigo, que es pena eterna, así en el cuerpo como en el alma.','Introducción');
INSERT INTO "heidelberg_catechism_search_content" VALUES(12,'Si por el justo juicio de Dios merecemos penas temporales y eternas, ¿No hay alguna posibilidad de liberarnos de estas penas y reconciliarnos con Dios?','Dios quiere que se dé satisfacción a su justicia: por eso es necesario que la satisfagamos eternamente por nosotros mismos o por algún otro.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(13,'¿Pero podemos satisfacerla por nosotros mismos?','De ninguna manera: antes acrecentamos cada día nuestra deuda.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(14,'¿Podría hallar ese alguien que siendo simple criatura pagase por nosotros?','No, Primero porque Dios no quiere castigar en otra criatura, la culpa de la cual el hombre es responsable, Segundo, porque una simple criatura es incapaz de soportar la ira eterna de Dios contra el pecado y liberar a otros de ella.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(15,'¿Entonces, que mediador y redentor debemos buscar?','Uno que sea el verdadero hombre y perfectamente justo y que sea más poderoso que todas las criaturas, es decir, que sea al mismo tiempo verdadero Dios.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(16,'¿Por qué debe ser verdadero hombre y perfectamente justo?','Porque la justicia de Dios exige que la misma naturaleza humana que pecó, pague por el pecado; el hombre que es pecador, no puede pagar por otros.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(17,'¿Por qué debe ser también verdadero Dios?','Para que, por la potencia de su divinidad, pueda llevar en su humanidad la carga de la ira de Dios, y reparar y restituir en nosotros la justicia y la vida.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(18,'Mas ¿Quién es este mediador, que al mismo tiempo es verdadero Dios, y verdadero hombre perfectamente justo?','Nuestro Señor Jesucristo, el cual nos ha sido hecho por Dios, sabiduría y justicia, satisfacción y perfecta redención.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(19,'¿De dónde sabes todo esto?','Del Santo Evangelio, del cual Dios reveló primeramente en el paraíso, y después lo anunció por los santos patriarcas y profetas, y lo hizo representar por los sacrificios y las demás ceremonias de la Ley: y al fin lo cumplió por su Hijo unigénito.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(20,'¿Son salvados por Cristo todos los hombres que perecieron en Adán?','No todos, sino sólo aquellos que por la verdadera fe son incorporados en El y aceptan sus beneficios.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(21,'¿Qué es la verdadera fe?','No es sólo un seguro conocimiento por el cual considero cierto todo lo que el Señor nos ha revelado en su palabra, sino también una verdadera confianza que el Espíritu Santo, infunde en mi corazón, por el Evangelio, dándome la seguridad, de que no sólo a otros sino también a mí mismo Dios otorga la remisión de pecados, la justicia y la vida eterna, y eso de pura gracia y solamente por los méritos de Jesucristo.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(22,'¿Qué es lo que debe creer el Cristiano?','Todo lo que se nos ha prometido en el Santo Evangelio, sumariamente contenido en el Símbolo Apostólico, en cuyos artículos se expresa la fe universal e infalible de todos los cristianos.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(23,'¿Qué dicen estos artículos?','Creo en Dios Padre, todopoderoso, Creador del cielo y de la tierra. Creo en Jesucristo su único hijo, nuestro Señor; que fue concebido por el Espíritu Santo, nació de María Virgen; padeció bajo el poder de Poncio Pilato, fue crucificado, muerto y sepultado; descendió a los infiernos, y al tercer día resucitó de entre los muertos; subió a los cielos; está sentado a la diestra de Dios, Padre todopoderoso, de donde vendrá a juzgar a los vivos y a los muertos. Creo en el espíritu Santo; una Santa Iglesia cristiana católica, la Comunión de los Santos; la remisión de los pecados, la resurrección del cuerpo y la vida eterna. Amén.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(24,'¿En cuántas partes se dividen estos artículos?','En tres. La Primera: De Dios Padre y de nuestra creación. La Segunda: De Dios Hijo y de nuestra redención. La Tercera: De Dios Espíritu Santo y nuestra santificación.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(25,'Si no hay más que una Esencia Divina, ¿Por qué nombras tres: Padre, Hijo y Espíritu Santo?','Porque Dios se manifestó así en su palabra, de manera que estas tres personas son el único, verdadero y eterno Dios.','La Redención del Hombre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(26,'¿Qué crees cuando dices: creo en Dios Padre Todopoderoso, creador del cielo y de la tierra?','Creo en el Padre de nuestro Señor Jesucristo, quien de la nada creó el cielo y de la tierra, con todo lo que en ellos hay, sustentándolo y gobernándolo todo por su eterno consejo y providencia, es mi Dios y mi Padre por amor de su hijo Jesucristo, En él confío de tal manera que no dudo de que me proveerá de todo lo necesario para mi alma y mi cuerpo. Y aún más, creo que todos los males que puedo sufrir por su voluntad, en este valle de lágrimas, los convertirá en bien para mi salvación. Él puede hacerlo como Dios todopoderoso, y quiere hacerlo como Padre benigno y fiel.','De Dios Padre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(27,'¿Qué es la providencia de Dios?','Es el poder de Dios omnipotente y presente en todo lugar, por el cual sustenta y gobierna el cielo, la tierra y todas las criaturas de tal manera, que todo lo que la tierra produce, la lluvia y la sequía, la fertilidad y la esterilidad, la comida y la bebida, la salud y la enfermedad, riquezas y pobrezas, y finalmente todas las cosas no acontecen sin razón alguna como por azar, sino por su consejo y voluntad paternal.','De Dios Padre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(28,'¿Qué utilidad tiene para nosotros este conocimiento de la creación y providencia divina?','Que en toda adversidad tengamos paciencia, y en la prosperidad seamos agradecidos, y tengamos puesta en el futuro, toda nuestra esperanza en Dios nuestro padre fidelísimo, sabiendo con certeza que no hay cosa que nos puede apartar de su amor, pues todas las criaturas, están sujetas a su poder de tal manera que no pueden hacer nada sin su voluntad.','De Dios Padre');
INSERT INTO "heidelberg_catechism_search_content" VALUES(29,'¿Por qué el hijo de Dios es llamado Jesús, que significa Salvador?','Porque nos salva y libra de todos nuestros pecados, y porque en ningún otro se debe buscar ni se puede hallar salvación.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(30,'¿Creen pues también en el único Salvador Jesús, aquellos que buscan su salvación en los santos, o en sí mismos o en cualquiera otra parte?','No, porque aunque de boca se gloríen de tenerle por Salvador, de hecho niegan al único Salvador Jesús: pues necesariamente resulta, o que Jesús no es perfecto Salvador o que aquellos que con verdadera fe le reciben por Salvador tienen que poseer en El todo lo necesario para su salvación.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(31,'¿Por qué se le llama Cristo, es decir: ungido?','Porque fue ordenado del Padre y ungido del Espíritu Santo, para ser nuestro supremo profeta y maestro, que nos ha revelado plenamente el secreto consejo y voluntad de Dios acerca de nuestra redención, para ser nuestro único y supremo pontífice quien por el sólo sacrificio de su cuer po nos ha redimido, e intercede continuamente delante del Padre por nosotros, para ser nuestro eterno Rey que nos gobierna por su palabra y su espíritu y nos guarda y conserva la redención que nos ha adquirido.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(32,'Pues, ¿Porqué te llaman Cristiano?','Porque por la fe soy miembro de Jesucristo y participante de su unción, para que confiese su nombre y me ofrezca a Él, en sacrificio vivo y agradable y que en esta vida luche contra el pecado y Satanás con una conciencia limpia y buena y que, después de esta vida reine con Cristo eternamente sobre todas las criaturas.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(33,'¿Por qué se llama a Cristo el unigénito hijo de Dios, si nosotros también somos hijos de Dios?','Porque Cristo es el hijo eterno y natural de Dios; pero nosotros hemos sido adoptados por gracia como hijos de Dios por amor de él.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(34,'¿Por qué le llamamos nuestro Señor?','Por que rescatando nuestros cuerpos y almas de los pecados, no con oro o plata, sino con su preciosa sangre, y librándonos del poder del Diablo, nos ha hecho suyos.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(35,'¿Qué crees cuando dices: que fue concebido por el Espíritu santo y nació de María virgen?','Que el eterno Hijo de Dios, el cual es y permanece verdadero y eterno Dios, tomó la naturaleza verdaderamente humana de la carne y sangre de la virgen María, por obra del Espíritu Santo, para que juntamente fuese la verdadera simiente de David, semejante a sus hermanos excepto en el pecado.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(36,'¿Qué fruto sacas de la santa concepción y nacimiento de Cristo?','Que es nuestro Mediador, y con su inocencia y perfecta santidad cubre mis pecados en los cuales he sido concebido y nacido, para que no aparezcan en la presencia de Dios.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(37,'¿Qué es lo que crees cuando dices: padeció?','Que todo el tiempo que en este mundo vivió y especialmente al fin de su vida, sostenía en el cuerpo y el alma la ira de Dios contra el pecado de todo el género humano, para que con su pasión, como único sacrificio propiciatorio, librara nuestro cuerpo y alma de la eterna condenación, y nos alcanzase la gracia de Dios, la justicia y la vida eterna.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(38,'¿Por qué padeció bajo el poder de Poncio Pilato juez?','Para que, inocente, condenado por el juez político, nos librase del severo juicio de Dios, que había de venir sobre nosotros.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(39,'¿Es más importante el haber sido crucificado, que morir de otro modo?','Sí, porque este género de muerte me garantiza que él cargó sobre sí mismo la maldición sentenciada sobre mí, por cuanto la muerte de cruz era maldita de Dios.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(40,'¿Por qué fue necesario que Cristo se humillase hasta la muerte?','Porque la justicia de Dios no se podía satisfacer por nuestros pecados, sino con la misma muerte del Hijo de Dios.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(41,'¿Por qué fue también sepultado?','Para testificar que estaba verdaderamente muerto.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(42,'Ya que Cristo murió por nosotros, ¿Por qué hemos de morir también nosotros?','Nuestra muerte no es una satisfacción por nuestros pecados, sino una liberación del pecado y un paso hacia la vida eterna.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(43,'¿Qué provecho recibimos además del sacrificio y muerte de Cristo en la cruz?','Por su poder nuestro viejo hombre está crucificado, muerto y sepultado juntamente con Él, para que, en adelante, no reinen más en nosotros las perversas concupiscencias y deseos de la carne, sino que nos ofrezcamos a Él en sacrificio agradable.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(44,'¿Por qué se añade: descendió a los infiernos?','Para que en mis extremados dolores y grandísimas tentaciones me asegure y me sostenga con este consuelo, de que mi Señor Jesucristo, por medio de las inexplicables angustias, tormentos, espantos y turbaciones infernales de su alma, en los cuales fue sumido en toda su pasión, pero especialmente clavado en la cruz, me ha librado de las ansias y tormentos del infierno.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(45,'¿Qué nos aprovecha la resurrección de Cristo?','Primero: Por su resurrección ha vencido a la muerte, para hacernos participantes de aquella justicia que conquistó por su muerte. Segundo: También nosotros somos resucitados ahora por su poder a una nueva vida. Tercero: la resurrección de Cristo, cabeza nuestra, es una cierta prenda de nuestra gloriosa resurrección.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(46,'¿Qué entiendes por: subió a los cielos?','Que Cristo, a la vista de sus discípulos, fue elevado de la tierra al cielo y que está allí para nuestro bien, hasta que vuelva a juzgar a los vivos y a los muertos.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(47,'Luego, ¿No está Cristo con nosotros hasta el fin del mundo como lo prometido?.','Cristo es verdadero Dios y verdadero hombre: en cuanto a la naturaleza humana ahora ya no está en la tierra, pero en cuanto a su deidad, majestad, gracia y espíritu en ningún momen to está ausente de nosotros.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(48,'Pero si la naturaleza humana no está en todas partes donde está la divina ¿No se separan con esto las dos naturalezas en Cristo?','De ninguna manera: porque dado que la divinidad es incomprensibley está presente en todo lugar, resulta necesariamente que en efecto está fuera de la naturalezahumana que ha tomado, perocon todo y con eso está en ella y queda unida a ella personalmente.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(49,'¿Qué beneficios nos da la ascensión de Cristo al cielo?','Primero: Él es nuestro intercesor en el cielo delante del Padre. Segundo: Que tenemos nuestra carne en el cielo para que por ello, como una garantía, estemos seguros, de que él siendo nuestra cabeza, nos atraerá a sí como miembros suyos. Tercero. Que desde allí nos envía su Espíritu como prenda recíproca, por cuya virtud buscamos, no las cosas de la tierra sino las de arriba, donde está sentado a la diestra de Dios.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(50,'¿Por qué se añade: está sentado a la Diestra de Dios, Padre todopodero so?','PorqueCristo subió al cielo para mostrarse allí como cabeza de su Iglesia, por quien el Padre gobierna todas las cosas.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(51,'¿De qué nos sirve esta gloria de Cristo, nuestra cabeza?','Primero: Para que el Espíritu Santo derrame en nosotros, sus miembros, los dones celestiales, y Segundo: Para protegernos y ampararnos de todos nuestros enemigos.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(52,'¿Qué consuelo te ofrece la vuelta de Cristo para juzgar a los vivos y a los muertos?','Que en todas las miserias y persecuciones, con plena confianza, espero del cielo como juez, a Aquel mismo que primeramente se puso delante del juicio de Dios por mí y alejó de mí toda maldición; el cual echará a todos los enemigos suyos y míos en las penas eternas; y a mí, con todos los elegidos, me conducirá al gozo del cielo y a la gloria eterna.','De Dios Hijo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(53,'¿Qué crees del Espíritu Santo?','Que con el Eterno Padre e Hijo, es verdadero y eterno Dios. Y que viene a morar en mí para que, por la verdadera fe, me haga participante de Cristo y de todos sus beneficios, me consuele y quede conmigo eternamente.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(54,'¿Qué crees de la santa Iglesia cristiana católica?','Que el Hijo de Dios, desde el principio hasta el fin del mundo, de todo el género humano, congrega, guarda y protege para sí, por su Espíritu y su palabra en la unidad de la verdadera fe, una comunidad, elegida para la vida eterna; de la cual yo soy un miembro vivo y permaneceré para siempre.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(55,'¿Qué entiendes por la comunión de los santos?','Primero, que todos los fieles en general y cada uno en particular, como miembros del Señor Jesucristo, tienen la comunión de Él y de todos sus bienes y dones. Segundo, que cada uno debe sentirse obligado a emplear con amor y gozo los dones que ha recibido, utilizándolos en beneficio de los demás.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(56,'¿Qué crees de la remisión de los pecados?','Creo que Dios, por la satisfacción de Cristo, no quiere acordarse jamás de mis pecados, ni de mi naturaleza corrompida, con la cual debo luchar toda la vida, sino que gratuitamente me otorga la justicia de Cristo para que yo nunca venga a condenación.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(57,'¿Qué consuelo te da la resurrección de la carne?','Que no sólo mi alma después de esta vida será llevada en el mismo instante a Cristo, su cabeza, sino que también está mi carne, siendo resucitada por la potencia de Cristo, será de nuevo unida a mi alma y hecha conforme al glorioso cuerpo de Cristo.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(58,'¿Qué consolación te ofreceel artículo de la vida eterna?','Que ahora siento en mi corazón un principio de la vida eterna, después de esta vida, gozaré de una cumplida y perfecta bienaventuranza que ningún ojo vio ni oído oyó, ni entendimiento humano comprendió, y esto para que ella alabe a Dios para siempre ( b).','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(59,'¿Qué te aprovecha el creer en todas estas cosas?','Que delante de Dios soy justo en Jesucristo,y heredero de la vida eterna.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(60,'¿Cómo eres justo ante Dios?','Por la sola verdadera fe en Jesucristo, de tal suerte que, aunque mi conciencia me acuse de haber pecado gravemente contra todos los mandamientos de Dios, no habiendo guardado jamás ninguno de ellos,y estando siempre inclinado a todo mal, sin merecimiento alguno mío, sólo por su gracia, Dios me imputa y da la perfecta satisfacción, justicia y santidad de Cristo como si no hubiera yo tenido, ni cometido algún pecado, antes bien como si yo mismo hubiera cumplido aquella obediencia que Cristo cumplió por mí, con tal que yo abrace estas gracias y beneficios con verdadera fe.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(61,'¿Por qué afirmas ser justo sólo por la fe?','No porque agrade a Dios por la dignidad de mi fe, sino porque sólo la satisfacción, justicia y santidad de Cristo, son mi propia justicia delante de Dios, y que yo no puedo cumplir de otro modo que por la fe.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(62,'¿Por qué no pueden justificarnos ante Dios las buenas obras, aunque sólo sea una parte?','Porque es necesario que aquella justicia, que ha de aparecer delante del juicio de Dios, sea perfectamente cumplida y de todo punto conforme a la Ley Divina; y nuestras buenas obras, aun las mejores en esta vida, son imperfectas y contaminadas de pecado.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(63,'Luego, ¿Cómo es posible que nuestras obras no merezcan nada, si Dios promete remunerarlas en la vida presente y en la venidera?','Esta remuneración no se da por merecimiento, sino por gracia.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(64,'Pero esta doctrina, ¿no hace a los hombres negligentes e impíos?','No, porque es imposible que no produzcan frutos de gratitud los que por la fe verdadera han sido injertados en Cristo.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(65,'Si sólo la fe nos hace participantes de Cristo y de todos sus beneficios, dime, ¿de dónde procede esta fe?','Del Espíritu Santo que la hace obrar por la predicación del Santo Evangelio, encendiendo nuestros corazones, y confirmándola por el uso de los sacramentos.','De Dios Espíritu Santo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(66,'¿Qué son los Sacramentos?','Son señales sagradas y visibles, y sellos instituidos por Dios, para sernos declarada mejor y sellada por ellos la promesa del Evangelio; a saber, que la remisión de los pecados y la vida eterna, por aquel único sacrificio de Cristo cumplido en la cruz, se nos da de gracia no solamente a todos los creyentes en general, sino también a cada uno en particular.','De los Sacramentos');
INSERT INTO "heidelberg_catechism_search_content" VALUES(67,'Entonces la palabra y los Sacramentos ¿tienen como fin llevar nuestra fe al sacrificio de Cristo cumplido en la cruz, como el único fundamento de nuestra salvación?','Así es, porque el Espíritu Santo nos enseña por el Evangelio y confirma por los Sacramentos, que toda nuestra salud está puesta en el único sacrificio de Cristo ofrecido por nosotros en la cruz.','De los Sacramentos');
INSERT INTO "heidelberg_catechism_search_content" VALUES(68,'¿Cuántos sacramentos ha instituido Cristo en el Nuevo Testamento?','Dos: El Santo Bautismo y la Santa Cena.','De los Sacramentos');
INSERT INTO "heidelberg_catechism_search_content" VALUES(69,'¿Por qué el Santo bautismo te asegura y recuerda que eres participante de aquel único sacrificio de Cristo, hecho en la Cruz?','Porque Cristo ha instituido, el lavamiento exterior del agua, añadiendo esta promesa, que tan ciertamente soy lavado con su sangre y Espíritu de las inmundicias de mi alma, es a saber, de todos mis pecados, como soy rociado y lavado exteriormente con el agua, con la cual se suelen limpiar las suciedades del cuerpo.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(70,'¿Qué es ser lavado con la sangre y el Espíritu de Cristo?','Es recibir de la gracia de Dios, la remisión de los pecados, por la sangre de Cristo, que derramó por nosotros en su sacrificio en la Cruz. Y también ser renovados y santificados por el Espíritu Santo, para ser miembros de Cristo, a fin de que muramos al pecado y vivamos santa e irreprensiblemente.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(71,'¿Dónde prometió Cristo que Él nos quiere limpiar tan ciertamente por su sangre y Espíritu como somos lavados por el agua del bautismo?','En la institución del Bautismo, cuyas palabras son éstas: "Id, enseñad a todas las gentes, bautizándolas en el nombre del Padre y del Hijo, y del Espíritu Santo" (Mateo 28:19) 3 "El que creyere y fuere bautizado, será salvo; mas el que no creyere, será condenado" (Marcos 16:16). 4 Esta misma promesa se repite cuando las Sagradas escrituras llaman al bautismo "lavamiento de la regeneración y ablución de pecados" (Tito 3:5, Hechos 22:16).5','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(72,'¿Es el lavamiento, la purificación misma de los pecados?','No: porque sólo la sangre de Jesucristo y el Espíritu Santo nos limpia y purifica de todo pecado.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(73,'Entonces, ¿Por qué llama el Espíritu Santo al bautismo el lavado de la regeneración y la purificación de los pecados?','Dios no habla así sin una razón justificada, pues Él, no sólo quiere enseñarnos que nuestros pecados se purifican por la sangre y el Espíritu de Cristo, como las suciedades del cuerpo por el agua, sino más aún: certificarnos por este divino símbolo y prenda que verdaderamente somos limpiados por el lavamiento interior y espiritual de nuestros pecados, de la misma manera que somos lavados exteriormente por el agua visible.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(74,'¿Se ha de bautizar también a los niños?','Naturalmente, porque están comprendidos, como los adultos, en el pacto, y pertenecen a la iglesia de Dios. Tanto a éstos como a los adultos se les promete por la sangre de Cristo, la remisión de los pecados y el Espíritu Santo, obrador de la fe; por esto, y como señal de este pacto, deben ser incorporados a la Iglesia de Dios y diferenciados de los hijos de los infieles, así como se hacía en el pacto del Antiguo Testamento por la circuncisión, cuyo sustito es el Bautismo en el Nuevo Pacto.','Del Santo Bautismo');
INSERT INTO "heidelberg_catechism_search_content" VALUES(75,'¿Cómo te asegura y confirma la Santa Cena que eres hecho participante de aquel único sacrificio de Cristo, ofrecido en la cruz, y de todos sus bienes?','Porque Cristo me ha mandado, y también a todos los fieles, comer de este pan partido y beber de esta copa en memoria suya, añadiendo esta promesa: Primero, que su cuerpo ha sido ofrecido y sacrificado por mí en la cruz, y su sangre derramada por mis pecados, tan cierto como que veo con mis ojos que el pan del Señor es partido para mí y que me es ofrecida la copa. Y Segundo, que El tan cierto alimenta mi alma para la vida eterna con su cuerpo crucificado y con su sangre derramada, como yo recibo con la boca corporal de la mano del ministro el pan y el vino, símbolos del cuerpo y de la sangre del Señor.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(76,'¿Qué significa comer el cuerpo sacrificado de Cristo y beber su sangre derramada?','Significa, no sólo abrazar con firme confianza del alma toda la pasión y muerte de Cristo, y por este medio alcanzar la remisión de pecados y la vida eterna, sino unirse más y más a su santísimo cuerpo por el Espíritu Santo, el cual habita juntamente en Cristo y en nosotros de tal manera, que, aunque El esté en el cielo y nosotros en la tierra, todavía somos carne de su carne y huesos de sus huesos, y que, de un mismo espíritu, (como todos los miembros del cuerpo por una sola alma) somos vivificados y gobernados para siempre.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(77,'¿Dónde prometió Cristo, que tan ciertamente dará a los creyentes en comida y en bebida su cuerpo y sangre, como comen de este pan roto y beben de este vaso?','En la institución de la cena, cuyas palabras fueron: Nuestro Señor Jesucristo, la noche que fue entregado, tomó el pan, y habiendo dado gracias, lo partió y dijo: Tomad, comed, esto es mi cuerpo que por vosotros es partido; haced en memoria de mí. Asimismo tomó también la copa, después de haber cenado, diciendo: Esta copa es el nuevo pacto en mi sangre;haced esto todas las veces que la bebereis, en memoria de mí. Así, pues, todas las veces que comiereis este pan y bebiereis esta copa, la muerte del Señor anunciáis hasta que él venga (1 Cor. 11:23-26).6 Pablo repite esta promesa cuando dice: La copa de bendición, que bendecimos, ¿no es la comunión de la sangre de Cristo?, El pan que partimos, ¿no es la comunión del cuerpo de Cristo? Siendo uno solo el pan, nosotros, con ser muchos, somos un cuerpo: pues todos participamos de aquel mismo pan (1 Cor. 10:16,17).7','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(78,'¿El pan y el vino se convierten sustancialmente en el mismo cuerpo y sangre de Cristo?','De ninguna manera, pues como el agua del Bautismo no se convierte en la sangre de Cristo, ni es la misma ablución de los pecados, sino solamente una señal y sello de aquellas cosas que nos son selladas en el Bautismo, así el pan de la Cena del Señor no es el mismo cuerpo, aunque por la naturaleza y uso de los sacramentos es llamado el cuerpo de Cristo.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(79,'¿Por qué llama Cristo al pan su cuerpo y a la copa su sangre, o el Nuevo Testamento en su sangre, y Pablo al pan y al vino la comunión del cuerpo y sangre de Cristo?','Cristo no habla así sin una razón poderosa, y no solamente para enseñarnos que, así como el pan y el vino sustentan la vida corporal, su cuerpo crucificado y su sangre derramada son la verdadera comida y bebida, que alimentan nuestras almas para la vida eterna, más aún, para asegurarnos por estas señales y sellos visibles, que por obra del Espíritu Santo somos participantes de su cuerpo y sangre tan cierto como que tomamos estos sagrados símbolos en su memoria y por la boca del cuerpo; y también que su pasión y obediencia son tan ciertamente nuestras ,como si nosotros mismos en nuestras personas hubiéramos sufrido la pena y satisfecho a Dios por nuestros pecados.8','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(80,'¿Quiénes son los que deben participar de la mesa del Señor?','Tan sólo aquellos que se duelan verdaderamente de haber ofendido a Dios con sus pecados, confiando en ser perdonados por el amor de Cristo y que las demás flaquezas quedarán cubiertas con su pasión y muerte. Y que también deseen fortalecer más y más su fe y mejorar su vida. Pero los hipócritas y los que no se arrepienten de verdad, comen y beben su condenación.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(81,'¿Deben admitirse también a esta Cena, los que por su confesión y vida se declaran infieles e impíos?','De ninguna manera, porque así se profana el pacto de Dios, y se provoca su ira sobre toda la congregación. Por lo cual, la Iglesia debe, según la orden de Cristo y de sus apóstoles (usando de las llaves del reino de los cielos), excomulgar y privar a los tales de la Cena, hasta que se arrepientan y rectifiquen su vida.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(82,'¿Qué son las llaves del reino de los cielos?','La predicación del Santo Evangelio y la disciplina eclesiástica: con los cuales se abre el cielo a los fieles, y se cierra a los infieles.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(83,'¿De qué manera se abre y se cierra el reino de los cielos por la predicación del Evangelio?','Cuando (según el mandamiento de Cristo) públicamente es anunciado y testificado a todos los fieles en general y a cada uno en particular, que todos los pecados les son perdonados por Dios, por los méritos de Cristo, todas las veces que abrazaren con verdadera fe la promesa del evangelio. Al contrario, a todos los infieles e hipócritas, se les anuncia que la ira de Dios y la condenación eterna  caerá sobre ellos mientras perseveraren en su maldad; según testimonio del Evangelio, Dios juzgará así en esta vida como en la otra.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(84,'¿De qué manera se cierra y se abre el reino de los cielos por la disciplina eclesiástica?','Cuando (según el mandamiento de Cristo) aquellos que bajo el nombre de cristianos se muestran en la doctrina o en la vida ajenos a Cristo, y después de haber sido fraternalmente amonestados en diversas ocasiones, no quieren apartarse de sus errores o maldades, son denunciados a la Iglesia o a los que han sido amonestados por ella. Y si aun no obedecen a la amonestación de éstos, por la prohibición de los sacramentos, son expulsados de la congregación cristiana, y por el mismo Dios, del reino de Cristo; y otra vez recibidos, como miembros de Cristo y de su Iglesia, cuando prometen enmienda y lo demuestran por sus obras.','De la Santa Cena de Nuestro Señor');
INSERT INTO "heidelberg_catechism_search_content" VALUES(85,'Si somos liberados por Cristo de todos nuestros pecados y miserias sin merecimiento alguno de nuestra parte, sino sólo por la misericordia de Dios ¿Por qué hemos de hacer buenas obras?','Porque después de que Cristo nos ha redimido con su sangre, nos renueva también con su Espíritu Santo a su imagen; a fin de que en toda nuestra vida nos mostremos agradecidos a Dios por tantos beneficios y que Él sea glorificado por nosotros. Además de esto para que cada uno de nosotros sea asegurado de su fe por los frutos. Y finalmente para que, también por la piedad e integridad de nuestra vida, ganemos a nuestro prójimo para Cristo.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search_content" VALUES(86,'Luego, ¿No pueden salvarse aquellos que siendo desagradecidos y perseverando en sus pecados no se conviertan a Dios de su maldad?','De ninguna manera, porque, como lo testifican las Sagradas Escrituras, no herederán el reino de Dios los fornicarios, los idólatras, los adúlteros, los ladrones, los avaros, los borrachos, los maldicientes.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search_content" VALUES(87,'¿De cuantas partes se compone el verdadero arrepentimiento y conversión al Señor?','De dos: la muerte del viejo hombre, y la vivificación del nuevo.9','De la Gratitud');
INSERT INTO "heidelberg_catechism_search_content" VALUES(88,'¿En qué consiste la muerte del hombre viejo?','En que sintamos pesar, de todo corazón, de haber ofendido a Dios con nuestros pecados, aborreciéndolos y evitándolos.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search_content" VALUES(89,'¿Qué es la vivificación del nuevo hombre?','Es alegrarse de todo corazón en Dios por Cristo, y desear vivir conforme a la voluntad de Dios, así como ejercitarse en toda buena obra.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search_content" VALUES(90,'¿Qué son las buenas obras?','Únicamente aquellas que se realizan con fe verdadera, conforme a la Ley de Dios, y se aplican solamente a su gloria; y no aquellas que están fundadas en nuestras buenas intenciones o sobre instituciones humanas.','De la Gratitud');
INSERT INTO "heidelberg_catechism_search_content" VALUES(91,'¿Cuál es la Ley de Dios?','Y habló Dios todas estas palabras (Éxodo 20:1-17): PRIMER MANDAMIENTO: No tendrás dioses ajenos delante de mí. SEGUNDO MANDAMIENTO: No te harás imagen, ni ninguna semejanza de lo que esté arriba en el cielo, ni abajo en la tierra, ni en las aguas debajo de la tierra, No te inclinarás a ellas, ni las honrarás; porque yo soy Jehová tu Dios, fuerte, celoso, que visitó la maldad de los padres sobre los hijos, hasta la tercera y cuarta generación, de los que me aborrecen; y hago misericordia a millares, a los que me aman y guardan mis mandamientos. TERCER MANDAMIENTO: No tomarás el nombre de Jehová tu Dios en vano; porque no dará por inocente Jehová al que tomare su nombre en vano. CUARTO MANDAMIENTO: Acuérdate del día de reposo para santificarlo; seis días trabajarás, y harás toda su obra; mas el séptimo día es de reposo para Jehová tu Dios; no hagas en él obra alguna, tú ni tu hijo, ni tu hija ni tu siervo ni tu criada ni tu bestia, ni tu extranjero que está dentro de tus puertas. Porque en seis días hizo Jehová los cielos y la tierra, el mar y todas las cosas que en ellos hay, y reposó en el séptimo día; por tanto, Jehová bendijo el día de reposo y lo santificó. QUINTO MANDAMIENTO: Honra a tu padre y a tu madre, para que tus días se alarguen en la tierra que Jehová tu Dios te da. SEXTO MANDAMIENO: No matarás. SEPTIMO MANDAMIENO: No cometerás adulterio. OCTAVO MANDAMIENTO: No hurtarás. NOVENO MANDAMIENTO: No hablarás contra tu prójimo falso testimonio. DECIMO MANDAMIENTO: No codiciarás la casa de tu prójimo, no codiciarás la mujer de tu prójimo ni su siervo, ni su criada, ni su buey, ni su asno, ni cosa alguna de tu prójimo.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(92,'¿Cómo se dividen estos diez mandamientos?','En dos tablas: De las cuales la primera enseña lo que debemos hacer para con Dios; la segunda, lo que debemos hacer para con nuestro prójimo.10','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(93,'¿Qué manda Dios en el primer mandamiento?','Que yo, que deseo la salvación de mi alma, evite y huya de toda idolatría, hechicería, encantamiento, superstición, invocación de santos y de otras criaturas; y que conozca rectamente al único verdadero Dios, en El sólo confié con toda humildad y paciencia, a El que de todo corazónle ame, tema y reverencie; de tal manera que esté dispuesto a renunciar a todas las criaturas antes que cometer la menor cosa contra su voluntad.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(94,'¿Qué es idolatría?','Es poner en el lugar que sólo corresponde al Dios verdadero que se ha revelado por su Palabra, o junto a Él, cualquier otra cosa en la cual se ponga confianza.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(95,'¿Qué pide Dios en el segundo mandamiento?','Que no representemos a Dios por medio de alguna imagen o figura, y sólo le rindamos culto como Él ha mandado en su Palabra.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(96,'¿No es lícito hacer ninguna imagen?','Ni podemos, ni debemos representar a Dios de ninguna manera, y aun en el caso de que fuese lícito representar a las criaturas, Dios prohíbe hacer o poseer ninguna imagen destinada a ser adorada o empleada en su servicio.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(97,'¿No se podrían tolerar las imágenes en las iglesias, como si fuesen libros para enseñar a los ignorantes?','No, porque nosotros no debemos ser más sabios que Dios, que no quiere instruir a su pueblo por imágenes mudas, sino por la predicación viva de su Palabra.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(98,'¿Qué nos enseña el tercer mandamiento?','Que dejemos de blasfemar o profanar el nombre de Dios por medio de falsos juramentos y maldiciones, y aún inútiles juramentos; que no nos hagamos partícipes de tan horrendos pecados al callar cuando los oigamos. En una palabra: que no empleemos el santo nombre de Dios , mas que con temor y veneración, a fin de que Él sea rectamente confesado, invocado y glorificado por nuestras palabras y hechos.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(99,'¿Es tan grave pecado el profanar el nombre de Dios por medio de juramentos y blasfemias, que Dios también se enoja contra aquellos que no se opusieron y no lo prohibieron con todas sus fuerzas?','Sí, porque no hay mayor pecado ni cosa que a Dios más ofenda que el profanar su nombre, por lo cual mandó que esta maldad fuese castigada con la muerte.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(100,'¿Se puede jurar santamente en nombre de Dios?','Sí, cuando el magistrado o la necesidad así lo exijan para sostener y confirmar la fe y la verdad, para la gloria de Dios y el bien de nuestro prójimo. Pues tal manera de prestar juramento está fundada en la palabra de Dios y, en consecuencia, ha sido rectamente empleada por los santos, tanto en el Antiguo como en el Nuevo Testamento.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(101,'¿Es lícito jurar por los santos u otras criaturas?','No. Porque el legítimo juramento es una invocación de Dios, por la cual se le pide, que Él, como el que sólo ve los corazones, sea testigo de la verdad, y castigue si el juramento es falso; este honor le corresponde a Él.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(102,'¿Qué ordena Dios en el cuarto mandamiento?','Primero, que el ministerio de la Palabra y la enseñanza sean mantenidos, y que yo frecuente asiduamente la iglesia, la congregación de Dios, sobre todo el día de reposo, para oír la Palabra de Dios, y participar de los santos sacramentos, para invocar públicamente al Señor, y para contribuir cristianamente a ayudar a los necesitados. Además, que todos los días de mi vida cese de mal obrar, para que sea Dios mismo quien obre en mi corazón por su Espíritu, y de este modo pueda empezar en esta vida el Sábado eterno.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(103,'¿Qué manda Dios en el quinto mandamiento?','Que muestre a mi padre y a mi madre y a todos mis superiores, honor, amor y fidelidad, que me someta obedientemente a sus buenas enseñanzas y castigos, soportando  también pacientemente sus flaquezas, pues Dios quiere regirnos por medio de ellos.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(104,'¿Qué exige Dios en el sexto mandamiento?','Que ni por mis pensamientos, palabras, actitud y aún menos por mis actos, por mí mismo o por medio de otro, llegue a injuriar, odiar, ofender o matar a mí prójimo, por el contrario que, renuncie a todo deseo de venganza; que no me haga mal a mi mismo o me exponga temerariamente al peligro. Para impedir esto, el magistrado posee la espada.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(105,'¿Este mandamiento sólo prohíbe matar?','Al prohibir la muerte Dios nos enseña que Él detesta todo lo que de ello se origina, como la envidia, el odio, la ira y el deseo de venganza, considerando todo esto como verdadero homicidio.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(106,'¿Es suficiente, como hemos dicho, el no matar a nuestro prójimo?','No; pues Dios, condenando la envidia, el odio y la ira, quiere que amemos a nuesro prójimo como a nosotros mismos, usando para con él toda benignidad, mansedumbre, paciencia y misericordia, impidiendo hasta donde nos sea posible,el mal que le podría sobrevenir, haciendo bien incluso a nuestros enemigos.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(107,'¿Qué enseña el séptimo mandamiento?','Que Dios maldice toda deshonestidad, y en consecuencia nosotros debemos también aborrecerla de todo corazón y vivir casta y sobriamente, sea en el santo estado de matrimonio, o en otro estado.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(108,'¿En este mandamiento, prohíbe sólo Dios el adulterio y pecados semejantes?','Como nuestro cuerpo y alma son templo del Espíritu Santo, Dios quiere que conservemos ambos puros y santos.Para ello prohíbe toda impureza en nuestras acciones, nuestros gestos, nuestras palabras, nuestros pensamientos y deseos, y todo lo que incita al hombre a ello.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(109,'¿Qué prohíbe Dios en el octavo mandamiento?','Dios prohíbe no solamente el robo y la rapiña que castiga la autoridad , sino que llama también robo a todos los medios malos y engaños con los cuales tratamos de apoderarnos del bien de nuestro prójimo, ya sea por la fuerza por una apariencia de derecho, como son: el peso falso,la mala mercadería, la moneda falsa, la usura, o por cualquier otro medio prohibido por Dios. También prohíbe toda avaricia y todo uso inútil de sus dones.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(110,'¿Qué te ordena Dios en este mandamiento?','Buscar en la medida de mis fuerzas, aquello que sea útil a mi prójimo, de hacer con él lo que yo quisiera que él hiciese conmigo, y trabajar fielmente a fin de poder asistir a los necesitados en  su pobreza.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(111,'¿Qué se pide en el noveno mandamiento?','Que no levante falsos testimonios contra nadie, que no interprete mal las palabras de los demás, que no sea ni detractor ni calumniador. Que no ayude a condenar a nadie temerari amente y sin haberle escuchado; que huya de toda clase de mentira y engaño como obras propias del diablo, si no quiero provocar contra mí la gravísima ira de Dios, Que en los juicios como en cualquier otra ocasión, ame la verdad, la anuncie y la confiese sinceramente, Y por último que procure con todas mis fuerzas defender la honra y reputación de mi prójimo.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(112,'¿Qué ordena el décimo mandamiento?','Que ni por deseo o pensamiento nuestros corazones se rebelen jamás contra alguno de los mandamientos de Dios, sino que en todo tiempo aborrezcamos el pecado de todo corazón y nos deleitemos en toda justicia.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(113,'¿Pueden guardar perfectamente estos mandamientos los que son convertidos a Dios?','No, porque incluso los más santos, en tanto estén en esta vida, no cumplen más que con un pequeño principio de esta obediencia. Sin embargo, empiezan a vivir firmemente no sólo según algunos, sino todos los mandamientos de Dios.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(114,'Entonces, ¿Por qué quiere Dios que se nos predique tan rigurosamente los diez mandamientos, si no hay nadie que pueda observarlos perfectamente en esta vida?','Primeramente, para que durante toda nuestra vida conozcamos más y más, cuán grande es la inclinación de nuestra naturaleza a pecar, y así busquemos con más fervor la remisión de nuestros pecados y la justicia de Cristo. Después , que nos apliquemos sin descanso a suplicar a Dios la gracia de su Espíritu Santo, para que cada día seamos más renovados a su imagen, hasta que, después de esta vida, alcancemos la perfección que nos es propuesta.','De la Ley');
INSERT INTO "heidelberg_catechism_search_content" VALUES(115,'¿Por qué es necesaria la oración a los cristianos?','Porque es el punto principal de nuestro agradecimiento que Dios pide de nosotros, y porque El quiere dar su gracia y su Espíritu Santo sólo a aquellos que se lo piden con oraciones ardientes y continuas, dándole gracias.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(116,'¿Qué es necesario en la oración para que ésta agrade a Dios y sea oída por Él?','Primero, que pidamos de todo corazón, al solo y verdadero Dios, el cual se ha manifestado en su palabra, todas las cosas que El desea que le pidamos. Segundo, que reconociendo sinceramente toda nuestra pobreza y miseria, nos humillemos delante de su majestad. Y por último que apoyándonos sobre este firme fundamento, sepamos que, pese a nuestra indignidad, El escuchará nuestra oración por amor del Señor Jesucristo, como nos lo ha prometido en su palabra.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(117,'¿Qué nos ha mandado Dios que le pidamos?','Todo lo que es necesario para el alma y para el cuerpo, lo cual, nuestro Señor Jesucristo, ha incluido en la oración que él mismo nos ha enseñado.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(118,'¿Qué dice esta oración?','Padre nuestro que estas en los cielos, santificado sea tu nombre. Venga tu reino. Sea hecha u voluntad, como en el cielo, así también en la tierra. Danos hoy nuestro pan cotidiano, y perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores. Y no nos metas en tentación, mas líbranos del mal. [Porque tuyo es el reino, y el poder, y la gloria, por todos los siglos. Amén.]','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(119,'¿Por qué nos pide nuestro Señor Jesucristo que nos dirijamos a Dios diciendo: "Padre nuestro?"','Para despertar en nosotros, desde el principio de nuestra oración, el respeto filial y la confianza en Dios que deben se elfundamento de nuestra oración. Es a saber, que Dios ha venido a ser nuestro Padre por Jesucristo, y nos concede con mayor seguridad las cosas que le pedimos con fe, que nuestros padres nos otorgan la cosas de este mundo.11','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(120,'¿Por qué se añade: Que estás en los cielos?','A fin de que no tengamos ninguna idea terrestre de la majestad celestial de Dios, y esperemos de su omnipotencia lo que necesitamos para nuestro cuerpo y nuestra alma.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(121,'¿Cuál es la primera súplica?','Santificado sea tu nombre, es decir, concédenos ante todo que te conozcamos rectamente, y que santifiquemos y celebremos tu omnipotencia, sabiduría, bondad, justicia, misericordia y verdad, que se manifiestan en toda tus obras. Concédenos también, que toda nuestra vida, en pensamiento, palabra y obra, sea siempre dirigida a este fin: que tu santísimo nombre no sea por nosotros blasfemado ni menospreciado, sino honrado y glorificado.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(122,'¿Cuál es su segunda súplica?','Venga tu reino, es decir; reina de tal modo sobre nosotros por tu Palabra y Espíritu, que nos sometamos cada vez más y más a Ti. Conserva y aumenta tu iglesia. Destruye las obras del diablo y todo poder que se levante contra Ti, lo mismo que todos los consejos que se toman contra tu Palabra, hasta que la plenitud de tu reino venga, cuando Tú serás todo en todos.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(123,'¿Cuál es la tercera súplica?','Sea hecha tu voluntad, como en el cielo, así también en la tierra. Es decir, haz que nosotros y todos los hombres, renunciemos a nuestra propia voluntad, y con toda humildad obedezcamos la tuya que es la única buena, para que cada uno de nosotros cumpla su deber y vocación, tan fiel y gozosamente como lo hacen los ángeles en el cielo.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(124,'¿Cuál es la cuarta súplica?','Danos hoy nuestro pan cotidiano, es decir, dígnate proveernos de todo lo que es necesario para el cuerpo, a fin de que, por ello reconozcamos que Tú eres la única fuente de todo bien, y que, ni nuestras necesidades, ni trabajo, ni incluso los bienes que Tú nos concedes, no nos aprovechan antes nos dañan sin tu bendición. Por tanto, concédenos que apartemos nuestra confianza de todas las criaturas, para ponerla sólo en Ti.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(125,'¿Cuál es la quinta súplica?','Perdónanos nuestras deudas, como también nosotros perdonamos a nuestros deudores; es decir: por la preciosa sangre de Jesucristo, dígnate no imputarnos, a nosotros pobres pecadores, nuestros pecados ni la maldad que está arraigada en nosotros, así como nosotros sentimos, por este testimonio de tu gracia, el firme propósito de perdonar de todo corazón a nuestro prójimo.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(126,'¿Cuál es la sexta súplica?','No nos metas en tentación, más líbranos del mal; es decir, dado que nosotros mismos no podríamos subsistir un solo instante, y dado que, nuestros enemigos mortales como son: Satanás, el mundo y nuestra propia carne, nos hacen continua guerra; dígnate sostenernos y fortificarnos por la potencia de tu Espíritu Santo, para que podamos resistirles valerosamente, y no sucumbamos en ese combate espiritual, hasta que logremos finalmente la victoria.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(127,'¿Cómo concluyes esta oración?','Porque tuyo es el reino, el poder, y la gloria, por todos los siglos. Esto es: Te pedimos todo esto, porque siendo nuestro Rey Todopoderoso, Tú puedes y quieres concedernos toda clase de bien, y esto para que, no a nosotros, sino a tu santo nombre sea todo gloria por todos los siglos.','Oración');
INSERT INTO "heidelberg_catechism_search_content" VALUES(128,'¿Qué significa la palabra: Amén? 12','Amén quiere decir: esto es verdadero y cierto. Porque mi oración es más ciertamente escuchada por Dios, que lo que yo siento en mi corazón, que he deseado de Él.','Oración');
