BEGIN TRANSACTION;
CREATE TABLE document_sources (
    document_key TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    language_code TEXT NOT NULL,
    source_filename TEXT NOT NULL,
    source_sha256 TEXT NOT NULL,
    attribution TEXT NOT NULL,
    source_url TEXT NOT NULL,
    content_version INTEGER NOT NULL CHECK (content_version > 0)
);
CREATE TABLE heidelberg_catechism (
    question_number INTEGER PRIMARY KEY CHECK (question_number > 0),
    question TEXT NOT NULL CHECK (length(trim(question)) > 0),
    answer TEXT NOT NULL CHECK (length(trim(answer)) > 0),
    section TEXT NOT NULL,
    language_code TEXT NOT NULL,
    source_page_start INTEGER NOT NULL CHECK (source_page_start > 0),
    source_page_end INTEGER NOT NULL CHECK (source_page_end >= source_page_start),
    document_key TEXT NOT NULL DEFAULT 'heidelberg_catechism'
        REFERENCES document_sources(document_key)
);
CREATE VIRTUAL TABLE heidelberg_catechism_search USING fts4(
    question, answer, section, tokenize=unicode61
);
CREATE TABLE 'heidelberg_catechism_search_content'(docid INTEGER PRIMARY KEY, 'c0question', 'c1answer', 'c2section');
CREATE TABLE 'heidelberg_catechism_search_docsize'(docid INTEGER PRIMARY KEY, size BLOB);
CREATE TABLE 'heidelberg_catechism_search_segdir'(level INTEGER,idx INTEGER,start_block INTEGER,leaves_end_block INTEGER,end_block INTEGER,root BLOB,PRIMARY KEY(level, idx));
CREATE TABLE 'heidelberg_catechism_search_segments'(blockid INTEGER PRIMARY KEY, block BLOB);
CREATE TABLE 'heidelberg_catechism_search_stat'(id INTEGER PRIMARY KEY, value BLOB);
COMMIT;
PRAGMA user_version = 1;
